INSERT INTO reform_catalog VALUES
('TTHC-BT-01', '1.116909', 'Thực hiện trợ cấp xã hội và nhận chăm sóc, nuôi dưỡng, hỗ trợ kinh phí nhận chăm sóc, nuôi dưỡng hằng tháng', 'Bảo trợ xã hội', 'Tiếp nhận tại Trung tâm Phục vụ hành chính công bất kỳ trong tỉnh An Giang. Phòng Văn hóa - Xã hội thẩm định, Chủ tịch UBND cấp xã quyết định.', '07 ngày làm việc (56 giờ làm việc)', 'Tra cứu phí, lệ phí theo công bố của cơ quan tiếp nhận', 'https://candang.angiang.gov.vn/sites/default/files/2026/11/van-ban/4937-qd-ubndsignedsigned.pdf', '{"trinh_tu": "Trung tâm tiếp nhận, kiểm tra và số hóa hồ sơ hợp lệ. Chuyên viên Phòng Văn hóa - Xã hội thẩm định, lãnh đạo phòng kiểm tra và trình Chủ tịch UBND cấp xã quyết định. Văn thư phát hành và Trung tâm trả kết quả.", "co_quan_thuc_hien": "Tiếp nhận tại Trung tâm Phục vụ hành chính công bất kỳ trong tỉnh An Giang. Phòng Văn hóa - Xã hội thẩm định, Chủ tịch UBND cấp xã quyết định.", "thanh_phan_ho_so": "Mẫu số 01 khi đề nghị hưởng trợ cấp xã hội hằng tháng\nMẫu số 02 khi đề nghị hỗ trợ kinh phí nhận chăm sóc, nuôi dưỡng hằng tháng", "thoi_han_le_phi": "07 ngày làm việc (56 giờ làm việc) – Tra cứu phí, lệ phí theo công bố của cơ quan tiếp nhận", "can_cu_phap_ly": "335/2026/NĐ-CP\n4937/QĐ-UBND"}'),
('TTHC-BT-02', '1.116910', 'Hỗ trợ chi phí mai táng cho đối tượng bảo trợ xã hội', 'Bảo trợ xã hội', '- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).
- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.', 'Thủ tục: Hỗ trợ chi phí mai táng cho đối tượng bảo trợ xã hội. Cơ quan có thẩm quyền giải quyết: Bộ Y tế. Thời hạn giải quyết: DIRECT: 03 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ | ONLINE: 03 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ | POSTAL: 03 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ. Mức phí/lệ phí: Theo quy định của HĐND cấp tỉnh/thành phố.', 'Theo quy định của HĐND cấp tỉnh/thành phố', 'https://dichvucong.gov.vn (API ID: 01a0f66e-63a3-749a-a9d8-2dcbeda6af79)', '{"trinh_tu": "- Bước 1: Cá nhân, cơ quan, đơn vị chịu trách nhiệm mai táng cho đối tượng làm hồ sơ theo quy định gửi Chủ tịch Ủy ban nhân dân cấp xã nơi cư trú hoặc Chủ tịch Ủy ban nhân dân cấp xã nơi đối tượng chết, nơi tổ chức mai táng cho đối tượng (đối với trường hợp trợ giúp khẩn cấp).\n\n- Bước 2: Trong thời hạn 03 ngày làm việc, kể từ ngày nhận được Tờ khai của cá nhân, cơ quan, đơn vị tổ chức đứng ra mai táng cho đối tượng, Chủ tịch Ủy ban nhân dân cấp xã xem xét, quyết định hỗ trợ chi phí mai táng và thực hiện chi trả kinh phí hỗ trợ theo quy định.\n- Trường hợp thực hiện liên thông điện tử nhóm thủ tục hành chính đăng ký khai tử, xoá đăng ký thường trú, giải quyết mai táng phí, tử tuất thì thủ tục hỗ trợ chi phí mai táng thực hiện theo quy định tại Điều 11, Điều 12, Điều 13, Điều 14 và Điều 15 Nghị định số 63/2024/NĐ-CP của Chính phủ quy định việc thực hiện liên thông điện tử 02 nhóm thủ tục hành chính: đăng ký khai sinh, đăng ký thường trú, cấp thẻ bảo hiểm y tế cho trẻ em dưới 6 tuổi; đăng ký khai tử, xoá đăng ký thường trú, giải quyết mai táng phí, tử tuất, được sửa đổi, bổ sung bởi Nghị định số 301/2026/NĐ-CP (Quyết định số 1868/QĐ-BTP ngày 10/8/2026 của Bộ trưởng Bộ Tư pháp về việc công bố 02 nhóm thủ tục hành chính liên thông điện tử được thay thế: Đăng ký khai sinh, đăng ký thường trú, cấp thẻ bảo hiểm y tế, cấp thẻ căn cước cho trẻ em dưới 6 tuổi; đăng ký khai tử, xoá đăng ký thường trú, giải quyết mai táng phí, tử tuất).\n- Việc tiếp nhận thủ tục hành chính không phụ thuộc vào địa giới hành chính thực hiện theo quy định của pháp luật về thực hiện thủ tục hành chính không phụ thuộc địa giới hành chính.", "co_quan_thuc_hien": "- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).\n- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.", "thanh_phan_ho_so": "Tờ khai đề nghị hỗ trợ chi phí mai táng (Mẫu số 03 ban hành kèm theo Nghị định số 335/2026/NĐ-CP)", "thoi_han_le_phi": "Thủ tục: Hỗ trợ chi phí mai táng cho đối tượng bảo trợ xã hội. Cơ quan có thẩm quyền giải quyết: Bộ Y tế. Thời hạn giải quyết: DIRECT: 03 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ | ONLINE: 03 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ | POSTAL: 03 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ. Mức phí/lệ phí: Theo quy định của HĐND cấp tỉnh/thành phố. – Theo quy định của HĐND cấp tỉnh/thành phố", "can_cu_phap_ly": "335/2026/NĐ-CP"}'),
('TTHC-BT-03', '1.116907', 'Tiếp nhận đối tượng bảo trợ xã hội có hoàn cảnh đặc biệt khó khăn vào cơ sở trợ giúp xã hội', 'Bảo trợ xã hội', '- Cơ quan tiếp nhận: Trung tâm Phục vụ hành chính công cấp xã (QĐ 4937/QĐ-UBND An Giang).
- Quy trình 2 tầng: UBND cấp xã thẩm tra, ký văn bản đề nghị → Chuyển Cơ sở trợ giúp xã hội xem xét, quyết định tiếp nhận.', 'Thủ tục: Tiếp nhận đối tượng bảo trợ xã hội có hoàn cảnh đặc biệt khó khăn vào cơ sở trợ giúp xã hội. Cơ quan có thẩm quyền giải quyết: Bộ Y tế. Thời hạn giải quyết: DIRECT: 05 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ | ONLINE: 05 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ | POSTAL: 05 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ. Mức phí/lệ phí: Theo quy định của HĐND cấp tỉnh/thành phố.', 'Theo quy định của HĐND cấp tỉnh/thành phố', 'https://dichvucong.gov.vn (API ID: 01a0f653-8729-706c-9cc8-c3234469d7cf)', '{"trinh_tu": "- Bước 1: Đối tượng hoặc người giám hộ, nhân viên công tác xã hội chuẩn bị hồ sơ theo quy định gửi Chủ tịch Uỷ ban nhân dân xã, phường, đặc khu nơi cư trú (sau đây gọi chung là cấp xã).\n - Bước 2: Trong thời hạn 03 ngày làm việc, kể từ ngày nhận được hồ sơ của đối tượng, Chủ tịch Ủy ban nhân dân cấp xã thực hiện xác thực thông tin liên quan của đối tượng với Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu tổng hợp quốc gia, Cơ sở dữ liệu chuyên ngành dùng chung, xem xét điều kiện của đối tượng và có văn bản gửi cơ sở trợ giúp xã hội kèm theo hồ sơ của đối tượng. Trường hợp đối tượng không đủ điều kiện tiếp nhận chăm sóc, nuôi dưỡng tại cơ sở trợ giúp xã hội thì Chủ tịch Ủy ban nhân dân cấp xã trả lời bằng văn bản và nêu rõ lý do;\n - Bước 3: Trong thời hạn 02 ngày làm việc, kể từ ngày nhận được văn bản đề nghị của Chủ tịch Ủy ban nhân dân cấp xã và hồ sơ của đối tượng, người đứng đầu cơ sở trợ giúp xã hội xem xét, quyết định tiếp nhận đối tượng vào nuôi dưỡng, chăm sóc tại cơ sở trợ giúp xã hội hoặc cung cấp dịch vụ chăm sóc tại cộng đồng phù hợp.\n Trường hợp không đủ điều kiện chăm sóc, nuôi dưỡng tại cơ sở trợ giúp xã hội, thì trả lời bằng văn bản và nêu rõ lý do.\n - Việc tiếp nhận thủ tục hành chính không phụ thuộc vào địa giới hành chính thực hiện theo quy định của pháp luật về thực hiện thủ tục hành chính không phụ thuộc địa giới hành chính.", "co_quan_thuc_hien": "- Cơ quan tiếp nhận: Trung tâm Phục vụ hành chính công cấp xã (QĐ 4937/QĐ-UBND An Giang).\n- Quy trình 2 tầng: UBND cấp xã thẩm tra, ký văn bản đề nghị → Chuyển Cơ sở trợ giúp xã hội xem xét, quyết định tiếp nhận.", "thanh_phan_ho_so": "Tờ khai đề nghị chăm sóc, nuôi dưỡng tại cơ sở trợ giúp xã hội (theo Mẫu số 04 ban hành kèm theo Nghị định số 335/2026/NĐ-CP).", "thoi_han_le_phi": "Thủ tục: Tiếp nhận đối tượng bảo trợ xã hội có hoàn cảnh đặc biệt khó khăn vào cơ sở trợ giúp xã hội. Cơ quan có thẩm quyền giải quyết: Bộ Y tế. Thời hạn giải quyết: DIRECT: 05 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ | ONLINE: 05 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ | POSTAL: 05 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ. Mức phí/lệ phí: Theo quy định của HĐND cấp tỉnh/thành phố. – Theo quy định của HĐND cấp tỉnh/thành phố", "can_cu_phap_ly": "335/2026/NĐ-CP"}'),
('TTHC-BT-04', '1.014028', 'Hỗ trợ chi phí mai táng đối với đối tượng hưởng trợ cấp hưu trí xã hội', 'Bảo trợ xã hội', '- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).
- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.', 'Thủ tục: Hỗ trợ chi phí mai táng đối với đối tượng hưởng trợ cấp hưu trí xã hội. Cơ quan có thẩm quyền giải quyết: Bộ Y tế. Thời hạn giải quyết: ONLINE: 03 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ | POSTAL: 03 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ | DIRECT: 03 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ. Mức phí/lệ phí: Miễn phí / Không thu lệ phí.', 'Miễn phí / Không thu lệ phí', 'https://dichvucong.gov.vn (API ID: 019d2bff-3508-7268-b54b-6ce79a8cbf0e)', '{"trinh_tu": "- Bước 1: Cá nhân, cơ quan, đơn vị chịu trách nhiệm mai táng cho đối tượng làm hồ sơ theo quy định, gửi Chủ tịch Ủy ban nhân dân cấp xã nơi cư trú.\n\n- Bước 2: Trong thời hạn 03 ngày làm việc, kể từ ngày nhận được Tờ khai của cá nhân, cơ quan, đơn vị tổ chức đứng ra mai táng cho đối tượng, Chủ tịch Ủy ban nhân dân cấp xã xem xét, quyết định hỗ trợ chi phí mai táng và thực hiện chi trả kinh phí hỗ trợ theo quy định.\nTrường hợp thực hiện liên thông điện tử nhóm thủ tục hành chính đăng ký khai tử, xoá đăng ký thường trú, giải quyết mai táng phí, tử tuất thì thủ tục hỗ trợ chi phí mai táng thực hiện theo quy định tại Điều 11, Điều 12, Điều 13, Điều 14 và Điều 15 Nghị định số 63/2024/NĐ-CP của Chính phủ quy định việc thực hiện liên thông điện tử 02 nhóm thủ tục hành chính: đăng ký khai sinh, đăng ký thường trú, cấp thẻ bảo hiểm y tế cho trẻ em dưới 6 tuổi; đăng ký khai tử, xoá đăng ký thường trú, giải quyết mai táng phí, tử tuất, được sửa đổi, bổ sung bởi Nghị định số 301/2026/NĐ-CP (Quyết định số 1868/QĐ-BTP ngày 10/8/2026 của Bộ trưởng Bộ Tư pháp về việc công bố 02 nhóm thủ tục hành chính liên thông điện tử được thay thế: Đăng ký khai sinh, đăng ký thường trú, cấp thẻ bảo hiểm y tế, cấp thẻ căn cước cho trẻ em dưới 6 tuổi; đăng ký khai tử, xoá đăng ký thường trú, giải quyết mai táng phí, tử tuất).\n- Việc tiếp nhận thủ tục hành chính không phụ thuộc vào địa giới hành chính thực hiện theo quy định của pháp luật về thực hiện thủ tục hành chính không phụ thuộc địa giới hành chính.", "co_quan_thuc_hien": "- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).\n- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.", "thanh_phan_ho_so": "Tờ khai đề nghị hỗ trợ chi phí mai táng (Mẫu số 03 ban hành kèm theo Nghị định số 335/2026/NĐ-CP)", "thoi_han_le_phi": "Thủ tục: Hỗ trợ chi phí mai táng đối với đối tượng hưởng trợ cấp hưu trí xã hội. Cơ quan có thẩm quyền giải quyết: Bộ Y tế. Thời hạn giải quyết: ONLINE: 03 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ | POSTAL: 03 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ | DIRECT: 03 ngày làm việc kể từ ngày nhận đủ hồ sơ hợp lệ. Mức phí/lệ phí: Miễn phí / Không thu lệ phí. – Miễn phí / Không thu lệ phí", "can_cu_phap_ly": "42/2025/NĐ-CP\n176/2025/NĐ-CP\n41/2024/QH15\n335/2026/NĐ-CP"}'),
('TTHC-BT-05', '3.000731', '[Chờ xác minh An Giang] Hỗ trợ chi phí mai táng / Trợ cấp xã hội đột xuất (đang đối chiếu QĐ 4937/QĐ-UBND)', 'Bảo trợ xã hội', '- Trạng thái dữ liệu: Đang chờ xác minh thủ tục tương ứng tại tỉnh An Giang theo QĐ 4937/QĐ-UBND (chỉ tra cứu tham khảo).', 'Thủ tục: Thủ tục hỗ trợ chi phí mai táng cho đối tượng được trợ cấp xã hội hàng tháng ở cộng đồng theo Điều 4 Quy định ban hành kèm theo Quyết định số 4937/QĐ-UBND ngày 02/11/2026 của UBND tỉnh An Giang. Cơ quan có thẩm quyền giải quyết: UBND tỉnh An Giang / UBND cấp xã theo phân cấp. Thời hạn giải quyết: DIRECT: 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ đầy đủ, hợp lệ. | ONLINE: 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ đầy đủ, hợp lệ. | POSTAL: 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ đầy đủ, hợp lệ.. Mức phí/lệ phí: Theo quy định của HĐND cấp tỉnh/thành phố.', 'Theo quy định của HĐND tỉnh An Giang', 'https://dichvucong.gov.vn (API ID: 01a09f35-59a6-7010-addd-5274bbb2cf7a)', '{"trinh_tu": "Đang chờ xác minh tại An Giang. Chỉ dùng để tra cứu.", "co_quan_thuc_hien": "Đang chờ xác minh tại An Giang. Chỉ dùng để tra cứu.", "thanh_phan_ho_so": "Đang chờ xác minh tại An Giang. Chỉ dùng để tra cứu.", "thoi_han_le_phi": "Đang chờ xác minh tại An Giang. Chỉ dùng để tra cứu.", "can_cu_phap_ly": "Đang chờ xác minh tại An Giang. Chỉ dùng để tra cứu."}'),
('TTHC-CR-01', '1.116788', 'Đăng ký thường trú', 'Cư trú', '- Cơ quan có thẩm quyền tiếp nhận & giải quyết: Công an cấp xã (ngành dọc Bộ Công an).
- Kênh nộp: Trực tiếp tại Công an cấp xã hoặc trực tuyến qua ứng dụng VNeID / Cổng Dịch vụ công Bộ Công an (không nộp vào hàng đợi duyệt của UBND xã).', 'Thủ tục: Đăng ký thường trú. Cơ quan có thẩm quyền giải quyết: Bộ Công an. Thời hạn giải quyết: DIRECT: - Nộp hồ sơ trực tiếp tại cơ quan đăng ký cư trú (áp dụng đối với trường hợp “Đăng ký thường trú” và “Tách hộ”).
- Thời hạn 07 ngày làm việc kể từ ngày nhận được hồ sơ đầy đủ và chính xác đối với trường hợp “Đăng ký thường trú”.
Trường hợp công dân nộp hồ sơ đăng ký thường trú và Tờ khai đề nghị xác nhận nơi thường xuyên đậu, đỗ; sử dụng phương tiện vào mục đích để ở hoặc Tờ khai xác nhận tình trạng chỗ ở hợp pháp, diện tích nhà ở tối thiểu để đăng ký thường trú, đăng ký tạm trú đến cơ quan đăng ký cư trú thì thời gian giải quyết của Ủy ban nhân dân cấp xã không tính vào thời hạn giải quyết hồ sơ đăng ký thường trú.
- Thời hạn 05 ngày làm việc kể từ ngày nhận được hồ sơ đầy đủ và chính xác đối với trường hợp “Xóa đăng ký thường trú” và “Tách hộ”. | ONLINE: - Thời hạn 07 ngày làm việc kể từ ngày nhận được hồ sơ đầy đủ và chính xác đối với trường hợp “Đăng ký thường trú”.
 Trường hợp công dân nộp hồ sơ đăng ký thường trú và Tờ khai đề nghị xác nhận nơi thường xuyên đậu, đỗ; sử dụng phương tiện vào mục đích để ở hoặc Tờ khai xác nhận tình trạng chỗ ở hợp pháp, diện tích nhà ở tối thiểu để đăng ký thường trú, đăng ký tạm trú đến cơ quan đăng ký cư trú thì thời gian giải quyết của Ủy ban nhân dân cấp xã không tính vào thời hạn giải quyết hồ sơ đăng ký thường trú.
- Thời hạn 05 ngày làm việc kể từ ngày nhận được hồ sơ đầy đủ và chính xác đối với trường hợp “Xóa đăng ký thường trú” và “Tách hộ”.
- Thời hạn 03 ngày làm việc kể từ ngày nhận được hồ sơ đầy đủ và chính xác đối với trường hợp “Điều chỉnh thông tin về cư trú trong Cơ sở dữ liệu về cư trú”.. Mức phí/lệ phí: Công dân nộp hồ sơ trực tiếp thu 20.000 đồng/lần đăng ký thường trú.', 'Công dân nộp hồ sơ trực tiếp thu 20.000 đồng/lần đăng ký thường trú', 'https://dichvucong.gov.vn (API id: 01a0e614-34b3-7355-929c-9f54d24e6bc0)', '{"trinh_tu": "Bước 1: Cá nhân, tổ chức chuẩn bị hồ sơ theo quy định của pháp luật.\n Bước 2: Cá nhân, tổ chức nộp hồ sơ đến Công an cấp xã.\n Bước 3: Khi tiếp nhận hồ sơ đăng ký thường trú, cán bộ đăng ký kiểm tra hồ sơ, đối chiếu các thông tin mà công dân đã kê khai với thông tin trong Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu về cư trú, cơ sở dữ liệu khác có liên quan, hệ thống thông tin để kiểm tra tính chính xác các thông tin. Đối chiếu với các quy định của pháp luật về cư trú và thực hiện như sau:\n - Trường hợp hồ sơ đầy đủ, chính xác theo quy định thì cán bộ đăng ký tiếp nhận hồ sơ và cấp Phiếu tiếp nhận hồ sơ và hẹn trả kết quả (mẫu CT04 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký.\n- Trường hợp hồ sơ chưa đầy đủ, chưa chính xác theo quy định thì cán bộ đăng ký trả lại hồ sơ và cấp Phiếu thông báo về việc giải quyết hồ sơ cư trú (mẫu CT06 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký; ghi rõ lý do trả lại và hướng dẫn chi tiết, cụ thể cho công dân. \nBước 4: Cá nhân, tổ chức nộp lệ phí đăng ký thường trú theo quy định.\nBước 5: Căn cứ theo ngày hẹn trên Phiếu tiếp nhận hồ sơ và hẹn trả kết quả để nhận thông báo kết quả giải quyết thủ tục đăng ký cư trú (nếu có).\n\nBước 1: Cá nhân, tổ chức chuẩn bị hồ sơ theo quy định của pháp luật.\nBước 2: Cá nhân, tổ chức nộp hồ sơ đến Công an cấp xã.\nBước 3: Khi tiếp nhận hồ sơ, cơ quan đăng ký cư trú kiểm tra tính pháp lý và nội dung hồ sơ:\n- Trường hợp hồ sơ đã đầy đủ, chính xác theo quy định thì cán bộ đăng ký tiếp nhận hồ sơ và cấp Phiếu tiếp nhận hồ sơ và hẹn trả kết quả (mẫu CT04 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký.\n- Trường hợp hồ sơ chưa đầy đủ, chưa chính xác theo quy định thì cán bộ đăng ký trả lại hồ sơ và cấp Phiếu thông báo về việc giải quyết hồ sơ cư trú (mẫu CT06 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký; ghi rõ lý do trả lại và hướng dẫn chi tiết, cụ thể cho công dân.\nBước 4: Cá nhân, tổ chức nộp lệ phí tách hộ theo quy định.\nBước 5: Căn cứ theo ngày hẹn trên Phiếu tiếp nhận hồ sơ và hẹn trả kết quả để nhận thông báo kết quả giải quyết thủ tục đăng ký cư trú (nếu có).\n\nBước 1: Cá nhân, tổ chức chuẩn bị hồ sơ theo quy định của pháp luật.\nBước 2: Cá nhân, tổ chức nộp hồ sơ đến Công an cấp xã.\nBước 3: Khi tiếp nhận hồ sơ, cơ quan đăng ký cư trú kiểm tra tính pháp lý và nội dung hồ sơ:\n- Trường hợp hồ sơ đã đầy đủ, chính xác theo quy định thì cán bộ đăng ký tiếp nhận hồ sơ và cấp Phiếu tiếp nhận hồ sơ và hẹn trả kết quả (mẫu CT04 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký.\n- Trường hợp hồ sơ chưa đầy đủ, chưa chính xác theo quy định thì cán bộ đăng ký trả lại hồ sơ và cấp Phiếu thông báo về việc giải quyết hồ sơ cư trú (mẫu CT06 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký; ghi rõ lý do trả lại và hướng dẫn chi tiết, cụ thể cho công dân. \nBước 4: Căn cứ theo ngày hẹn trên Phiếu tiếp nhận hồ sơ và hẹn trả kết quả để nhận thông báo kết quả giải quyết thủ tục đăng ký cư trú (nếu có).", "co_quan_thuc_hien": "- Cơ quan có thẩm quyền tiếp nhận & giải quyết: Công an cấp xã (ngành dọc Bộ Công an).\n- Kênh nộp: Trực tiếp tại Công an cấp xã hoặc trực tuyến qua ứng dụng VNeID / Cổng Dịch vụ công Bộ Công an (không nộp vào hàng đợi duyệt của UBND xã).", "thanh_phan_ho_so": "Tờ khai thay đổi thông tin cư trú (mẫu CT01 ban hành kèm theo Thông tư số 116/2026/TT-BCA) hoặc Tờ khai thay đổi thông tin cư trú dùng cho người Việt Nam định cư ở nước ngoài về Việt Nam sinh sống (mẫu CT02 ban hành kèm theo Thông tư số 116/2026/TT-BCA)\nThông tin chứng minh về chỗ ở hợp pháp được khai thác trong căn cước điện tử, tài khoản định danh điện tử trên hệ thống định danh và xác thực điện tử qua Ứng dụng định danh quốc gia hoặc trong Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu về cư trú, Hệ thống thông tin giải quyết thủ tục hành chính cấp bộ, cấp tỉnh hoặc cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành khác. Trường hợp không khai thác được thông tin thì công dân xuất trình giấy tờ, tài liệu chứng minh chỗ ở hợp pháp theo quy định tại khoản 2 Điều 5 Nghị định 154/2024/NĐ-CP ngày 26/11/2024 của Chính phủ\nHợp đồng, văn bản về việc cho thuê, cho mượn, cho ở nhờ chỗ ở hợp pháp được công chứng hoặc chứng thực theo quy định của pháp luật\nThông tin chứng minh đủ diện tích nhà ở để đăng ký thường trú tại chỗ ở hợp pháp do thuê, mượn, ở nhờ được khai thác trong căn cước điện tử, tài khoản định danh điện tử trên hệ thống định danh và xác thực điện tử qua Ứng dụng định danh quốc gia hoặc trong Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu về cư trú, Hệ thống thông tin giải quyết thủ tục hành chính cấp bộ, cấp tỉnh hoặc cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành khác. Trường hợp không khai thác được thông tin thì công dân xuất trình giấy tờ, tài liệu quy định tại khoản 2 Điều 5 Nghị định số 154/2024/NĐ-CP, trong đó có thể hiện diện tích nhà ở hoặc xác nhận của Ủy ban nhân dân cấp xã về điều kiện diện tích bình quân bảo đảm theo quy định của Hội đồng nhân dân tỉnh, thành phố trực thuộc trung ương theo Mẫu số 02 ban hành kèm theo Nghị định số 58/2026/NĐ-CP ngày 13/02/2026 của Chính phủ.\nGiấy tờ, tài liệu chứng minh là nhà tu hành, chức sắc, chức việc hoặc người khác hoạt động tôn giáo và được hoạt động tại cơ sở tôn giáo đó theo quy định của pháp luật về tín ngưỡng, tôn giáo đối với người quy định tại điểm a khoản 4 Điều 20 Luật Cư trú; giấy tờ, tài liệu chứng minh là người đại diện cơ sở tín ngưỡng đối với người quy định tại điểm b khoản 4 Điều 20 Luật Cư trú\nVăn bản xác nhận của Ủy ban nhân dân cấp xã về việc trong cơ sở tín ngưỡng, cơ sở tôn giáo có công trình phụ trợ là nhà ở.\nVăn bản xác nhận của Ủy ban nhân dân cấp xã về việc người đăng ký thường trú thuộc đối tượng quy định tại khoản 2 Điều 17 Luật Cư trú và việc trong cơ sở tín ngưỡng, cơ sở tôn giáo có công trình phụ trợ là nhà ở.\nVăn bản đề nghị của người đứng đầu cơ sở trợ giúp xã hội đối với người được cơ sở trợ giúp xã hội nhận chăm sóc, nuôi dưỡng, trợ giúp.\nGiấy tờ, tài liệu xác nhận về việc chăm sóc, nuôi dưỡng, trợ giúp.\nGiấy chứng nhận đăng ký phương tiện và giấy chứng nhận an toàn kỹ thuật và bảo vệ môi trường của phương tiện hoặc văn bản xác nhận của Ủy ban nhân dân cấp xã về việc sử dụng phương tiện đó vào mục đích để ở đối với phương tiện không thuộc đối tượng phải đăng ký, đăng kiểm (nội dung xác nhận tại mục 2 của Ủy ban nhân dân cấp xã tại Tờ khai đề nghị xác nhận nơi thường xuyên đậu, đỗ; sử dụng phương tiện vào mục đích để ở theo Mẫu số 01 ban hành kèm theo Nghị định số 58/2026/NĐ-CP)\nVăn bản xác nhận của Ủy ban nhân dân cấp xã về địa điểm phương tiện đăng ký đậu, đỗ thường xuyên trong trường hợp phương tiện không phải đăng ký hoặc nơi đăng ký phương tiện không trùng với nơi thường xuyên đậu, đỗ (nội dung xác nhận tại mục 1 của Ủy ban nhân dân cấp xã tại Tờ khai đề nghị xác nhận nơi thường xuyên đậu, đỗ; sử dụng phương tiện vào mục đích để ở theo Mẫu số 01 ban hành kèm theo Nghị định số 58/2026/NĐ-CP ngày 13/02/2026 của Chính phủ)\nĐối với Công an nhân dân: Giấy giới thiệu của Thủ trưởng đơn vị quản lý trực tiếp ghi rõ nội dung để làm thủ tục đăng ký thường trú và đơn vị có chỗ ở cho cán bộ chiến sĩ (ký tên, đóng dấu).\nĐối với Quân đội nhân dân: Giấy giới thiệu đăng ký thường trú của cơ quan, đơn vị cấp trung đoàn và tương đương trở lên (ký tên, đóng dấu)\n- Không yêu cầu xuất trình Giấy khai sinh đối với trường hợp trẻ em mới sinh đăng ký thường trú lần đầu. - Trong thời hạn tối đa 60 ngày kể từ ngày người chưa thành niên được đăng ký khai sinh thì phải thực hiện thủ tục đăng ký cư trú. - Trường hợp người cao tuổi, người chưa thành niên đã có thông tin về ngày, tháng, năm sinh trong Cơ sở dữ liệu quốc gia về dân cư thì không yêu cầu xuất trình giấy tờ chứng minh. - Trường hợp công dân đăng ký thường trú vào chỗ ở hợp pháp thuộc quyền sở hữu của mình mà chỗ ở hợp pháp đó có nhiều hơn một chủ sở hữu thì không cần có ý kiến đồng ý của những người đồng sở hữu. - Trường hợp đăng ký thường trú theo quy định tại điểm a khoản 2 Điều 20 Luật Cư trú mà chỗ ở hợp pháp có nhiều hơn một chủ sở hữu thì chỉ cần ý kiến đồng ý của ít nhất một chủ sở hữu. - Trường hợp đăng ký thường trú vào chỗ ở hợp pháp của chủ sở hữu là người bị mất năng lực hành vi dân sự, người có khó khăn trong nhận thức, làm chủ hành vi theo quy định của Bộ luật Dân sự, người dưới 18 tuổi, người bị tuyên bố mất tích, người đã chết thì chỉ cần lấy ý kiến đồng ý của một trong những người đại diện hợp pháp, người thừa kế của chủ sở hữu theo quy định của pháp luật. - Người có mối quan hệ với chủ sở hữu chỗ ở hợp pháp theo quy định tại điểm a khoản 2 Điều 20 Luật Cư trú mà chủ sở hữu không đăng ký thường trú tại chỗ ở hợp pháp đó và không thuộc trường hợp quy định tại Điều 23 Luật Cư trú hoặc người đăng ký thường trú có mối quan hệ với chủ hộ, thành viên hộ gia đình theo quy định tại điểm a khoản 2 Điều 20 Luật Cư trú mà nơi thường trú của chủ hộ, thành viên hộ gia đình đó là chỗ ở hợp pháp do thuê, mượn, ở nhờ thì hồ sơ đăng ký thường trú thực hiện theo khoản 2 Điều 21 Luật Cư trú. - Người đăng ký thường trú theo điều kiện quy định tại điểm a khoản 2 Điều 20 Luật Cư trú mà chỗ ở đăng ký thường trú là địa điểm quy định tại Điều 23 Luật Cư trú thì hồ sơ đăng ký thường trú không cần phải có ý kiến đồng ý của chủ sở hữu chỗ ở hợp pháp đó trong trường hợp không xác định được chủ sở hữu. - Trường hợp người đăng ký thường trú là người Việt Nam định cư ở nước ngoài còn quốc tịch Việt Nam thì trong hồ sơ đăng ký thường trú phải có hộ chiếu Việt Nam còn giá trị sử dụng; trường hợp không có hộ chiếu Việt Nam còn giá trị sử dụng thì phải có giấy tờ, tài liệu chứng minh có quốc tịch Việt Nam. - Trường hợp người nước ngoài được nhập quốc tịch Việt Nam khi đăng ký thường trú lần đầu phải có Quyết định của Chủ tịch nước về việc cho nhập quốc tịch Việt Nam. Người gốc Việt Nam được trở lại quốc tịch Việt Nam khi đăng ký thường trú lần đầu sau khi được cho trở lại quốc tịch Việt Nam phải có Quyết định của Chủ tịch nước về việc cho trở lại quốc tịch Việt Nam trừ trường hợp đã khai thác được thông tin trong Cơ sở dữ liệu quốc tịch. - Sĩ quan nghiệp vụ, hạ sĩ quan nghiệp vụ, sĩ quan chuyên môn kỹ thuật, hạ sĩ quan chuyên môn kỹ thuật, công nhân công an đã đăng ký thường trú tại đơn vị đóng quân mà chuyển đến chỗ ở hợp pháp mới ngoài đơn vị đóng quân và đủ điều kiện đăng ký thường trú, đề nghị đăng ký thường trú tại chỗ ở mới thì hồ sơ đăng ký thường trú phải kèm Giấy giới thiệu của Thủ trưởng đơn vị quản lý trực tiếp (ký tên và đóng dấu). - Sĩ quan, quân nhân chuyên nghiệp, công nhân, viên chức quốc phòng đã đăng ký thường trú vào nhà ở công vụ, đơn vị đóng quân khi chuyển đăng ký thường trú ra chỗ ở hợp pháp ngoài nơi nhà ở công vụ, nơi đơn vị đóng quân thì hồ sơ đăng ký thường trú tại chỗ ở mới phải kèm theo Giấy giới thiệu đăng ký thường trú của đơn vị đang công tác (ký tên và đóng dấu). - Trường hợp công dân không tự thực hiện thủ tục về cư trú thì được ủy quyền cho người khác thực hiện thủ tục về cư trú, trừ trường hợp người giám hộ, người đại diện thực hiện thủ tục về cư trú cho người được giám hộ, người được đại diện thì không phải ủy quyền.\nThông tin chứng minh thuộc trường hợp xóa đăng ký thường trú của công dân theo quy định tại điểm b, d, e, g, h, i khoản 1 Điều 24 Luật Cư trú trong Cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành và cơ sở dữ liệu khác được kết nối, chia sẻ với cơ quan đăng ký cư trú. Trường hợp thông tin chưa được kết nối, chia sẻ thì công dân xuất trình giấy tờ, tài liệu chứng minh thuộc một trong các trường hợp xóa đăng ký thường trú theo quy định tại điểm b, d, e, g, h, i khoản 1 Điều 24 Luật Cư trú.\nTrường hợp công dân không tự thực hiện thủ tục về cư trú thì được ủy quyền cho người khác thực hiện thủ tục về cư trú, trừ trường hợp người giám hộ, người đại diện thực hiện thủ tục về cư trú cho người được giám hộ, người được đại diện thì không phải ủy quyền.\nGiấy tờ, tài liệu chứng minh việc ly hôn và việc tiếp tục được sử dụng chỗ ở hợp pháp đó.\n- Không phải xuất trình giấy tờ, tài liệu chứng minh việc ly hôn trong trường hợp thông tin về việc ly hôn được khai thác trong Cơ sở dữ liệu hộ tịch điện tử. - Trường hợp công dân không tự thực hiện thủ tục về cư trú thì được ủy quyền cho người khác thực hiện thủ tục về cư trú, trừ trường hợp người giám hộ, người đại diện thực hiện thủ tục về cư trú cho người được giám hộ, người được đại diện thì không phải ủy quyền.\nGiấy tờ, tài liệu chứng minh việc thay chủ hộ (nếu có)\n- Đối với trường hợp cần lấy ý kiến của các thành viên trong hộ gia đình thì các thành viên trong hộ gia đình xác nhận nội dung ý kiến thông qua Ứng dụng định danh quốc gia hoặc văn bản ghi rõ nội dung ý kiến (văn bản này không phải công chứng, chứng thực). - Trường hợp công dân không tự thực hiện thủ tục về cư trú thì được ủy quyền cho người khác thực hiện thủ tục về cư trú, trừ trường hợp người giám hộ, người đại diện thực hiện thủ tục về cư trú cho người được giám hộ, người được đại diện thì không phải ủy quyền. *Thay đổi thông tin về hộ tịch so với thông tin đã được lưu trữ trong Cơ sở dữ liệu về cư trú và thay đổi địa chỉ nơi cư trú trong Cơ sở dữ liệu về cư trú do có sự điều chỉnh về địa giới đơn vị hành chính, tên đơn vị hành chính, tên đường, phố, tổ dân phố, thôn, xóm, làng, ấp, bản, buôn, phum, sóc, cách đánh số nhà: cơ quan đăng ký cư trú có trách nhiệm điều chỉnh, cập nhật việc thay đổi thông tin trong Cơ sở dữ liệu về cư trú.", "thoi_han_le_phi": "Thủ tục: Đăng ký thường trú. Cơ quan có thẩm quyền giải quyết: Bộ Công an. Thời hạn giải quyết: DIRECT: - Nộp hồ sơ trực tiếp tại cơ quan đăng ký cư trú (áp dụng đối với trường hợp “Đăng ký thường trú” và “Tách hộ”).\n- Thời hạn 07 ngày làm việc kể từ ngày nhận được hồ sơ đầy đủ và chính xác đối với trường hợp “Đăng ký thường trú”.\nTrường hợp công dân nộp hồ sơ đăng ký thường trú và Tờ khai đề nghị xác nhận nơi thường xuyên đậu, đỗ; sử dụng phương tiện vào mục đích để ở hoặc Tờ khai xác nhận tình trạng chỗ ở hợp pháp, diện tích nhà ở tối thiểu để đăng ký thường trú, đăng ký tạm trú đến cơ quan đăng ký cư trú thì thời gian giải quyết của Ủy ban nhân dân cấp xã không tính vào thời hạn giải quyết hồ sơ đăng ký thường trú.\n- Thời hạn 05 ngày làm việc kể từ ngày nhận được hồ sơ đầy đủ và chính xác đối với trường hợp “Xóa đăng ký thường trú” và “Tách hộ”. | ONLINE: - Thời hạn 07 ngày làm việc kể từ ngày nhận được hồ sơ đầy đủ và chính xác đối với trường hợp “Đăng ký thường trú”.\n Trường hợp công dân nộp hồ sơ đăng ký thường trú và Tờ khai đề nghị xác nhận nơi thường xuyên đậu, đỗ; sử dụng phương tiện vào mục đích để ở hoặc Tờ khai xác nhận tình trạng chỗ ở hợp pháp, diện tích nhà ở tối thiểu để đăng ký thường trú, đăng ký tạm trú đến cơ quan đăng ký cư trú thì thời gian giải quyết của Ủy ban nhân dân cấp xã không tính vào thời hạn giải quyết hồ sơ đăng ký thường trú.\n- Thời hạn 05 ngày làm việc kể từ ngày nhận được hồ sơ đầy đủ và chính xác đối với trường hợp “Xóa đăng ký thường trú” và “Tách hộ”.\n- Thời hạn 03 ngày làm việc kể từ ngày nhận được hồ sơ đầy đủ và chính xác đối với trường hợp “Điều chỉnh thông tin về cư trú trong Cơ sở dữ liệu về cư trú”.. Mức phí/lệ phí: Công dân nộp hồ sơ trực tiếp thu 20.000 đồng/lần đăng ký thường trú. – Công dân nộp hồ sơ trực tiếp thu 20.000 đồng/lần đăng ký thường trú", "can_cu_phap_ly": "154/2024/NĐ-CP\n54/2025/TT-BCA\n66.7/2025/NQ-CP\n29/2026/TT-BTC\n68/2020/QH14\n75/2022/TT-BTC\n116/2026/TT-BCA\n190/2021/TT-BQP"}'),
('TTHC-CR-02', '2.002913', 'Liên thông điện tử: Đăng ký khai tử, xóa đăng ký thường trú, giải quyết mai táng phí, tử tuất', 'Cư trú', '- Kênh nộp liên thông điện tử (NĐ 63/2024/NĐ-CP): Cổng Dịch vụ công Quốc gia / VNeID.
- 3 cơ quan xử lý độc lập: UBND cấp xã (Khai tử) • Công an cấp xã (Xóa thường trú) • VH-XH / BHXH (Mai táng phí, tử tuất).', 'Thủ tục: Liên thông điện tử: Đăng ký khai tử, xóa đăng ký thường trú, giải quyết mai táng phí, tử tuất. Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: ONLINE: - Đăng ký khai tử, xóa đăng ký thường trú, giải quyết trợ cấp mai táng, tử tuất đối với nhóm Người có công: không quá mười tám (18) ngày làm việc. 
- Đăng ký khai tử, xóa đăng ký thường trú, giải quyết hỗ trợ chi phí mai táng đối với nhóm đối tượng Bảo trợ xã hội: không quá sáu (06) ngày làm việc. Không quá mười một (11) ngày làm việc đối với trường hợp đối tượng là người từ đủ 80 tuổi trở lên đang hưởng trợ cấp tuất hằng tháng.
- Đăng ký khai tử, xóa đăng ký thường trú, trợ cấp mai táng, trợ cấp tử tuất đối với đối tượng do ngành Bảo hiểm xã hội giải quyết: không quá chín (09) ngày làm việc.
Trường hợp nhận hồ sơ sau 15 giờ thì thời gian được tính bắt đầu từ ngày làm việc tiếp theo.. Mức phí/lệ phí: Theo quy định của các TTHC tương ứng.', 'Theo quy định của các TTHC tương ứng', 'https://dichvucong.gov.vn (API ID: 01a03d95-035a-701a-af30-45899ccb145c)', '{"trinh_tu": "- Bước 1. Người yêu cầu truy cập vào Cổng Dịch vụ công quốc gia (tại địa chỉ dichvucong.gov.vn) hoặc trên ứng dụng VNeID, lựa chọn dịch vụ công liên thông Đăng ký khai tử, xóa đăng ký thường trú, giải quyết mai táng phí, tử tuất để thực hiện nộp hồ sơ trực tuyến và lệ phí theo quy định.\nNgười yêu cầu có thể lựa chọn thực hiện liên thông hai (02) thủ tục hành chính (Đăng ký khai tử, xóa đăng ký thường trú); hoặc ba (03) thủ tục hành chính (Đăng ký khai tử, xoá đăng ký thường trú, giải quyết mai táng phí); hoặc bốn (04) thủ tục hành chính (Đăng ký khai tử, xoá đăng ký thường trú, giải quyết mai táng phí, tử tuất), Phần mềm dịch vụ công liên thông sẽ điều chỉnh nội dung tờ khai điện tử và giấy tờ phải đính kèm theo nội dung liên thông mà người yêu cầu đã lựa chọn để người yêu cầu thực hiện nộp hồ sơ trực tuyến theo quy định.\nCác thông tin trong tờ khai điện tử được điền tự động đối với các thông tin đã có trong Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu hộ tịch, Cơ sở dữ liệu quốc gia về Bảo hiểm và cơ sở dữ liệu, hệ thống thông tin có liên quan khác. Cá nhân đăng nhập Cổng Dịch vụ công quốc gia hoặc Ứng dụng định danh quốc gia (VNeID) đề nghị giải quyết thủ tục hành chính thì không phải thực hiện ký số biểu mẫu điện tử tương tác.\n\n- Bước 2. Cổng Dịch vụ công quốc gia nhận thông tin thanh toán thành công từ nền tảng thanh toán; tiến hành bóc tách thành phần hồ sơ; thực hiện chuyển hồ sơ (bao gồm biểu mẫu điện tử tương tác, các giấy tờ đính kèm) tới Hệ thống thông tin giải quyết TTHC của Bộ Tư pháp qua Nền tảng chia sẻ và điều phối dữ liệu. Hệ thống thông tin giải quyết TTHC của Bộ Tư pháp đồng bộ hồ sơ về Hệ thống đăng ký, quản lý hộ tịch điện tử của Bộ Tư pháp. Hệ thống đăng ký, quản lý hộ tịch điện tử của Bộ Tư pháp tiếp nhận hồ sơ và phản hồi trạng thái cho Cổng Dịch vụ công quốc gia qua Hệ thống thông tin giải quyết TTHC của Bộ Tư pháp.\n\n- Bước 3. Giải quyết hồ sơ đăng ký khai tử\nNgười thực hiện công tác hộ tịch tại Ủy ban nhân dân cấp xã thực hiện nghiệp vụ đăng ký khai tử trên Hệ thống đăng ký, quản lý hộ tịch điện tử của Bộ Tư pháp. Thời gian giải quyết đăng ký khai tử trong 24 giờ kể từ thời điểm Hệ thống đăng ký, quản lý hộ tịch điện tử của Bộ Tư pháp nhận đủ hồ sơ hợp lệ. Trường hợp cần xác minh thì thời hạn giải quyết không quá 03 ngày làm việc.\nTrường hợp hồ sơ chưa đầy đủ hoặc không đủ điều kiện giải quyết: Người thực hiện công tác hộ tịch tại Ủy ban nhân dân cấp xã thực hiện thao tác trên Hệ thống đăng ký, quản lý hộ tịch điện tử của Bộ Tư pháp để gửi thông tin trạng thái hồ sơ đến Hệ thống thông tin giải quyết thủ tục hành chính của Bộ Tư pháp, sau đó Hệ thống thông tin giải quyết thủ tục hành chính của Bộ Tư pháp thông báo cho người yêu cầu qua Cổng Dịch vụ công quốc gia, ứng dụng VNeID, trong đó nêu rõ lý do đối với các trường hợp hồ sơ bị từ chối giải quyết hoặc nêu rõ loại giấy tờ, nội dung cần bổ sung trong thời gian không quá 24 giờ kể từ thời điểm nhận được hồ sơ điện tử trên hệ thống.\nTrường hợp cần bổ sung thành phần hồ sơ thì người yêu cầu có trách nhiệm hoàn thiện hồ sơ trong 07 ngày làm việc, nếu quá thời hạn này không bổ sung được thì người thực hiện công tác hộ tịch tại Ủy ban nhân dân cấp xã thực hiện thao tác trên Hệ thống đăng ký, quản lý hộ tịch điện tử của Bộ Tư pháp để dừng xử lý do không bổ sung theo quy định. Thông tin về việc dừng xử lý được gửi đến Hệ thống thông tin giải quyết thủ tục hành chính của Bộ Tư pháp để thông báo cho người yêu cầu qua Cổng Dịch vụ công quốc gia hoặc ứng dụng VNeID hoặc gửi tin nhắn điện thoại tự động của Cổng Dịch vụ công quốc gia.\n\n- Bước 4. Giải quyết hồ sơ xóa đăng ký thường trú và giải quyết mai táng phí, tử tuất\n+ Sau khi bản điện tử Trích lục khai tử được cấp, Hệ thống thông tin giải quyết thủ tục hành chính của Bộ Tư pháp tự động chuyển bản điện tử Trích lục khai tử đến Cổng Dịch vụ công quốc gia, sau đó Cổng Dịch vụ công quốc gia thực hiện chia sẻ dữ liệu đến Hệ thống thông tin quản lý cư trú để thực hiện xóa đăng ký thường trú. Trong thời hạn 01 ngày làm việc kể từ ngày tiếp nhận thông tin, cơ quan đăng ký cư trú thực hiện xóa đăng ký thường trú đối với công dân và cập nhật việc xóa đăng ký thường trú vào Cơ sở dữ liệu về cư trú, Cơ sở dữ liệu quốc gia về dân cư.\n+ Sau khi Hệ thống đăng ký, quản lý hộ tịch điện tử của Bộ Tư pháp chuyển bản điện tử Trích lục khai tử sang Hệ thống thông tin giải quyết thủ tục hành chính của Bộ Tư pháp để tự động đồng bộ tới Cổng Dịch vụ công quốc gia, Cổng Dịch vụ công quốc gia phân tách, chuyển hồ sơ điện tử (bao gồm biểu mẫu, tờ khai mà người yêu cầu đã kê khai, bản điện tử Trích lục khai tử và các thành phần hồ sơ liên quan) đến Hệ thống thông tin của ngành Bảo hiểm xã hội hoặc Hệ thống thông tin giải quyết thủ tục hành chính của Bộ Nội vụ hoặc Hệ thống thông tin giải quyết thủ tục hành chính của Bộ Y tế thực hiện giải quyết chế độ mai táng phí, tử tuất.\nTrường hợp đối tượng là người đang hưởng trợ cấp tuất hằng tháng, trợ cấp hằng tháng khác được hỗ trợ chi phí mai táng, mai táng phí, Cổng Dịch vụ công quốc gia tự động chuyển hồ sơ của đối tượng đến Hệ thống thông tin của ngành Bảo hiểm xã hội. Sau 02 ngày làm việc kể từ ngày nhận được hồ sơ, cơ quan Bảo hiểm xã hội có trách nhiệm giải quyết và chuyển quyết định thôi hưởng trợ cấp tuất hằng tháng về Cổng Dịch vụ công quốc gia để chuyển hồ sơ sang Hệ thống thông tin giải quyết thủ tục hành chính của Bộ Nội vụ hoặc Hệ thống thông tin giải quyết thủ tục hành chính của Bộ Y tế để giải quyết chi trả chế độ mai táng, tử tuất.\nThời hạn cơ quan Bảo hiểm xã hội giải quyết trợ cấp mai táng, trợ cấp tuất không quá 08 ngày làm việc; giải quyết thôi hưởng trợ cấp tuất hằng tháng không quá 02 ngày làm việc kể từ ngày nhận được hồ sơ điện tử từ Cổng Dịch vụ công quốc gia.\nThời hạn cơ quan y tế giải quyết hỗ trợ chi phí mai táng không quá 03 ngày làm việc kể từ ngày nhận được hồ sơ điện tử từ Cổng Dịch vụ công quốc gia.\nThời hạn cơ quan nội vụ giải quyết trợ cấp mai táng, trợ cấp tuất đối với người có công không quá 18 ngày làm việc kể từ ngày nhận được hồ sơ điện tử từ Cổng Dịch vụ công quốc gia.", "co_quan_thuc_hien": "- Kênh nộp liên thông điện tử (NĐ 63/2024/NĐ-CP): Cổng Dịch vụ công Quốc gia / VNeID.\n- 3 cơ quan xử lý độc lập: UBND cấp xã (Khai tử) • Công an cấp xã (Xóa thường trú) • VH-XH / BHXH (Mai táng phí, tử tuất).", "thanh_phan_ho_so": "Tờ khai điện tử (theo Mẫu số 02 ban hành kèm theo Nghị định số 301/2026/NĐ-CP).\nDữ liệu điện tử có ký số của Giấy báo tử được liên thông từ cơ sở khám bệnh, chữa bệnh với Cổng Dịch vụ công quốc gia hoặc bản điện tử Giấy báo tử do người yêu cầu đăng ký khai tử đính kèm trên Cổng Dịch vụ công quốc gia.Trường hợp không có Giấy báo tử thì người yêu cầu đăng ký khai tử có thể đính kèm bản chụp hoặc bản điện tử giấy tờ thay Giấy báo tử theo quy định pháp luật về hộ tịch.\nThông tin xác nhận của các thân nhân đồng ý cử người đại diện nhận trợ cấp tuất một lần được thực hiện qua ứng dụng VNeID hoặc đính kèm Tờ khai điện tử về việc cử người đại diện nhận trợ cấp tuất một lần theo hướng dẫn của Bảo hiểm xã hội Việt Nam. Thời hạn xác nhận qua ứng dụng VNeID không quá 05 ngày làm việc.\nTrường hợp thân nhân là con từ đủ 18 tuổi trở lên hoặc vợ, chồng; cha đẻ, mẹ đẻ; cha đẻ, mẹ đẻ của vợ hoặc của chồng; thành viên khác của gia đình chưa đủ tuổi theo quy định tại khoản 2 Điều 169 của Bộ luật Lao động mà người tham gia bảo hiểm xã hội đang có nghĩa vụ nuôi dưỡng theo quy định của pháp luật về hôn nhân và gia đình, nếu không có thu nhập hằng tháng hoặc có thu nhập hằng tháng nhưng thấp hơn mức tham chiếu và bị suy giảm khả năng lao động từ 81% trở lên thì đính kèm các thành phần hồ sơ sau: (i) Bản điện tử Biên bản giám định mức suy giảm khả năng lao động của Hội đồng Giám định y khoa đối với thân nhân bị suy giảm khả năng lao động từ 81% trở lên hoặc biên bản Giám định y khoa để hưởng các chính sách khác trước đó mà đủ điều kiện hưởng hoặc Giấy xác nhận khuyết tật mức độ đặc biệt nặng tương đương mức suy giảm khả năng lao động từ 81% trở lên. (ii) Hóa đơn, chứng từ thu phí giám định, bảng kê các nội dung giám định của cơ sở thực hiện Giám định y khoa trong trường hợp thanh toán phí Giám định y khoa. Trường hợp các thành phần hồ sơ trên là bản giấy thì phải thực hiện số hóa theo quy định tại Nghị định số 118/2025/NĐ-CP, được sửa đổi, bổ sung bởi Nghị định số 367/2025/NĐ-CP.\nTrường hợp người từ đủ 80 tuổi trở lên đang hưởng trợ cấp tuất hằng tháng chết thì bổ sung bản điện tử Quyết định thôi hưởng trợ cấp tuất hằng tháng. Bản điện tử này do Hệ thống thông tin của Bảo hiểm xã hội chuyển đến Phần mềm dịch vụ công liên thông.\nThông tin xác nhận của các thân nhân đồng thuận xác nhận người có công nuôi liệt sĩ được thực hiện qua ứng dụng VNeID hoặc đính kèm bản điện tử văn bản đồng thuận của các thân nhân xác nhận là người có công nuôi liệt sĩ. Thời hạn xác nhận qua ứng dụng VNeID không quá 05 ngày làm việc.\nTrường hợp thân nhân là con từ đủ 18 tuổi trở lên đang đi học thì đính kèm bản điện tử giấy xác nhận của cơ sở giáo dục nơi đang theo học hoặc bản điện tử Bằng tốt nghiệp trung học phổ thông nếu đang theo học tại cơ sở giáo dục nghề nghiệp hoặc giáo dục đại học hoặc giấy xác nhận của cơ sở giáo dục trung học phổ thông về thời điểm kết thúc học.\nTrường hợp thân nhân sống độc thân và không còn thân nhân hoặc mồ côi cả cha lẫn mẹ, Ủy ban nhân dân cấp xã có trách nhiệm hoàn thiện giấy xác nhận sống độc thân và không còn thân nhân hoặc mồ côi cả cha lẫn mẹ.\nTrường hợp thân nhân là con người có công với cách mạng từ đủ 18 tuổi trở lên bị khuyết tật nặng hoặc đặc biệt nặng sau khi đủ 18 tuổi mà không có thu nhập hằng tháng hoặc có thu nhập hằng tháng nhưng thấp hơn 0,6 lần mức chuẩn thì đính kèm giấy xác nhận khuyết tật theo quy định của Luật Người khuyết tật và giấy xác nhận thu nhập theo quy định hiện hành. Trường hợp con từ đủ 18 tuổi trở lên bị khuyết tật nặng, khuyết tật đặc biệt nặng từ nhỏ thì đính kèm giấy xác nhận khuyết tật theo quy định của Luật Người khuyết tật.\nTrường hợp các thành phần hồ sơ trên là bản giấy thì phải thực hiện số hóa theo quy định tại Nghị định số 107/2021/NĐ-CP của Chính phủ.", "thoi_han_le_phi": "Thủ tục: Liên thông điện tử: Đăng ký khai tử, xóa đăng ký thường trú, giải quyết mai táng phí, tử tuất. Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: ONLINE: - Đăng ký khai tử, xóa đăng ký thường trú, giải quyết trợ cấp mai táng, tử tuất đối với nhóm Người có công: không quá mười tám (18) ngày làm việc. \n- Đăng ký khai tử, xóa đăng ký thường trú, giải quyết hỗ trợ chi phí mai táng đối với nhóm đối tượng Bảo trợ xã hội: không quá sáu (06) ngày làm việc. Không quá mười một (11) ngày làm việc đối với trường hợp đối tượng là người từ đủ 80 tuổi trở lên đang hưởng trợ cấp tuất hằng tháng.\n- Đăng ký khai tử, xóa đăng ký thường trú, trợ cấp mai táng, trợ cấp tử tuất đối với đối tượng do ngành Bảo hiểm xã hội giải quyết: không quá chín (09) ngày làm việc.\nTrường hợp nhận hồ sơ sau 15 giờ thì thời gian được tính bắt đầu từ ngày làm việc tiếp theo.. Mức phí/lệ phí: Theo quy định của các TTHC tương ứng. – Theo quy định của các TTHC tương ứng", "can_cu_phap_ly": "Nghị định số 301/2026/NĐ-CP"}'),
('TTHC-CR-03', '1.116789', 'Đăng ký tạm trú', 'Cư trú', '- Cơ quan có thẩm quyền tiếp nhận & giải quyết: Công an cấp xã (ngành dọc Bộ Công an).
- Kênh nộp: Trực tiếp tại Công an cấp xã hoặc trực tuyến qua ứng dụng VNeID / Cổng Dịch vụ công Bộ Công an (không nộp vào hàng đợi duyệt của UBND xã).', 'Thủ tục: Đăng ký tạm trú. Cơ quan có thẩm quyền giải quyết: Bộ Công an. Thời hạn giải quyết: DIRECT: a) Đối với trường hợp “Đăng ký tạm trú”, “Gia hạn tạm trú”
- Đăng ký tạm trú, gia hạn tạm trú (cá nhân, hộ gia đình):
+ Trường hợp công dân nộp hồ sơ trực tiếp thu 15.000 đồng/lần đăng ký.
- Đăng ký tạm trú theo danh sách, gia hạn tạm trú theo danh sách:
+ Trường hợp công dân nộp hồ sơ trực tiếp thu 10.000 đồng/người/lần đăng ký.
b) Đối với trường hợp “Xóa đăng ký tạm trú” 
Không thu lệ phí. | ONLINE: a) Đối với trường hợp “Đăng ký tạm trú”, “Gia hạn tạm trú”
- Đăng ký tạm trú, gia hạn tạm trú (cá nhân, hộ gia đình):
+ Trường hợp công dân nộp hồ sơ qua Cổng dịch vụ công quốc gia thu 7.000 đồng/lần đăng ký.
- Đăng ký tạm trú theo danh sách, gia hạn tạm trú theo danh sách:
+ Trường hợp công dân nộp hồ sơ qua Cổng dịch vụ công quốc gia thu 5.000 đồng/người/lần đăng ký.
- Công dân nộp hồ sơ qua Ứng dụng định danh quốc gia từ ngày 01/4/2026 đến 31/12/2026 thì được miễn lệ phí.
- Công dân thuộc diện được miễn phí theo quy định tại Điều 4 Thông tư số 75/2022/TT-BTC ngày 22/12/2022 quy định mức thu, chế độ thu, nộp và quản lý lệ phí đăng ký cư trú được sửa đổi, bổ sung tại Thông tư số 71/2025/TT-BTC ngày 01/7/2025 của Bộ trưởng Bộ Tài chính thì công dân phải xuất trình giấy tờ chứng minh thuộc diện được miễn trừ trường hợp thông tin đã có trong Cơ sở dữ liệu quốc gia về dân cư hoặc Cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành mà đã được kết nối với Cơ sở dữ liệu quốc gia về dân cư.
b) Đối với trường hợp “Xóa đăng ký tạm trú” 
Không thu lệ phí.. Mức phí/lệ phí: Đăng ký tạm trú, gia hạn tạm trú (cá nhân, hộ gia đình): Trường hợp công dân nộp hồ sơ qua Cổng dịch vụ công quốc gia thu 7.000 đồng/lần đăng ký..', 'Đăng ký tạm trú, gia hạn tạm trú (cá nhân, hộ gia đình): Trường hợp công dân nộp hồ sơ qua Cổng dịch vụ công quốc gia thu 7.000 đồng/lần đăng ký.', 'https://dichvucong.gov.vn (API ID: 01a0f011-315c-7373-9678-d13f6e83bbb3)', '{"trinh_tu": "Bước 1: Cá nhân, tổ chức chuẩn bị hồ sơ theo quy định của pháp luật.\n Bước 2: Cá nhân, tổ chức nộp hồ sơ đến Công an cấp xã.\n Bước 3: Khi tiếp nhận hồ sơ đăng ký tạm trú, cán bộ đăng ký kiểm tra hồ sơ, đối chiếu các thông tin mà công dân đã khai báo với thông tin trong Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu về cư trú, cơ sở dữ liệu khác có liên quan, hệ thống thông tin để kiểm tra tính chính xác các thông tin. Đối chiếu với các quy định của pháp luật về cư trú và thực hiện như sau:\n- Trường hợp hồ sơ đã đầy đủ, chính xác theo quy định thì cán bộ đăng ký tiếp nhận hồ sơ và cấp Phiếu tiếp nhận hồ sơ và hẹn trả kết quả (mẫu CT04 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký.\n- Trường hợp hồ sơ chưa đầy đủ, chưa chính xác theo quy định thì cán bộ đăng ký trả lại hồ sơ và cấp Phiếu thông báo về việc giải quyết hồ sơ cư trú (mẫu CT06 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký; ghi rõ lý do trả lại và hướng dẫn chi tiết, cụ thể cho công dân.\nBước 4: Cá nhân, tổ chức nộp lệ phí đăng ký tạm trú theo quy định.\nBước 5: Căn cứ theo ngày hẹn trên Phiếu tiếp nhận hồ sơ và hẹn trả kết quả để nhận thông báo kết quả giải quyết thủ tục đăng ký cư trú (nếu có).\n\nBước 1: Cá nhân, tổ chức chuẩn bị hồ sơ theo quy định của pháp luật.\nBước 2: Cá nhân, tổ chức nộp hồ sơ đến Công an cấp xã.\nBước 3: Khi tiếp nhận hồ sơ gia hạn tạm trú, cơ quan đăng ký cư trú kiểm tra tính pháp lý và nội dung hồ sơ:\n- Trường hợp hồ sơ đã đầy đủ, chính xác theo quy định thì cán bộ đăng ký tiếp nhận hồ sơ và cấp Phiếu tiếp nhận hồ sơ và hẹn trả kết quả (mẫu CT04 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký.\n- Trường hợp hồ sơ chưa đầy đủ, chưa chính xác theo quy định thì cán bộ đăng ký trả lại hồ sơ và cấp Phiếu thông báo về việc giải quyết hồ sơ cư trú (mẫu CT06 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký; ghi rõ lý do trả lại và hướng dẫn chi tiết, cụ thể cho công dân.\n Bước 4: Cá nhân, tổ chức nộp lệ phí gia hạn tạm trú theo quy định.\n Bước 5: Căn cứ theo ngày hẹn trên Phiếu tiếp nhận hồ sơ và hẹn trả kết quả để nhận thông báo kết quả giải quyết thủ tục đăng ký cư trú (nếu có).\n\nBước 1: Cá nhân, tổ chức chuẩn bị hồ sơ theo quy định của pháp luật.\nBước 2: Cá nhân, tổ chức nộp hồ sơ đến Công an cấp xã.\nBước 3: Khi tiếp nhận hồ sơ xóa đăng ký tạm trú, cơ quan đăng ký cư trú kiểm tra tính pháp lý và nội dung hồ sơ:\n- Trường hợp hồ sơ đã đầy đủ, chính xác theo quy định thì cán bộ đăng ký tiếp nhận hồ sơ và cấp Phiếu tiếp nhận hồ sơ và hẹn trả kết quả (mẫu CT04 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký.\n- Trường hợp hồ sơ chưa đầy đủ, chưa chính xác theo quy định thì cán bộ đăng ký trả lại hồ sơ và cấp Phiếu thông báo về việc giải quyết hồ sơ cư trú (mẫu CT06 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký; ghi rõ lý do trả lại và hướng dẫn chi tiết, cụ thể cho công dân.\nBước 4: Căn cứ theo ngày hẹn trên Phiếu tiếp nhận hồ sơ và hẹn trả kết quả để nhận thông báo kết quả giải quyết thủ tục đăng ký cư trú (nếu có).", "co_quan_thuc_hien": "- Cơ quan có thẩm quyền tiếp nhận & giải quyết: Công an cấp xã (ngành dọc Bộ Công an).\n- Kênh nộp: Trực tiếp tại Công an cấp xã hoặc trực tuyến qua ứng dụng VNeID / Cổng Dịch vụ công Bộ Công an (không nộp vào hàng đợi duyệt của UBND xã).", "thanh_phan_ho_so": "Tờ khai thay đổi thông tin cư trú (mẫu CT01 ban hành kèm theo Thông tư số 116/2026/TT-BCA) hoặc Tờ khai thay đổi thông tin cư trú dùng cho người Việt Nam định cư ở nước ngoài về Việt Nam sinh sống (mẫu CT02 ban hành kèm theo Thông tư số 116/2026/TT-BCA)\nThông tin chứng minh về chỗ ở hợp pháp được khai thác trong căn cước điện tử, tài khoản định danh điện tử trên hệ thống định danh và xác thực điện tử qua Ứng dụng định danh quốc gia hoặc trong Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu về cư trú, Hệ thống thông tin giải quyết thủ tục hành chính cấp bộ, cấp tỉnh hoặc cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành khác. Trường hợp không khai thác được thông tin thì công dân xuất trình giấy tờ, tài liệu chứng minh chỗ ở hợp pháp theo quy định tại khoản 3 Điều 5 Nghị định 154/2024/NĐ-CP ngày 26/11/2024 của Chính phủ được sửa đổi, bổ sung bởi Nghị định số 58/2026/NĐ-CP của Chính phủ ngày 13/02/2026\nThông tin chứng minh quan hệ nhân thân với chủ hộ, thành viên hộ gia đình được khai thác trong căn cước điện tử, tài khoản định danh điện tử trên hệ thống định danh và xác thực điện tử qua Ứng dụng định danh quốc gia hoặc trong Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu về cư trú, Hệ thống thông tin giải quyết thủ tục hành chính cấp bộ, cấp tỉnh hoặc cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành khác. Trường hợp không khai thác được thông tin thì công dân xuất trình giấy tờ, tài liệu chứng minh quan hệ nhân thân với chủ hộ tạm trú, thành viên hộ gia đình theo quy định tại khoản 2 Điều 6 Nghị định 154/2024/NĐ-CP ngày 26/11/2024 của Chính phủ\nHợp đồng, văn bản về việc cho thuê, cho mượn, cho ở nhờ không phải công chứng hoặc chứng thực\nĐối với Công an nhân dân: Giấy giới thiệu của Thủ trưởng đơn vị quản lý trực tiếp ghi rõ nội dung để làm thủ tục đăng ký tạm trú và đơn vị có chỗ ở cho cán bộ chiến sĩ (ký tên, đóng dấu).\nĐối với Quân đội nhân dân: Giấy giới thiệu đăng ký tạm trú của đơn vị cấp trung đoàn và tương đương trở lên.\nTờ khai thay đổi thông tin cư trú (của từng người) (mẫu CT01 ban hành kèm theo Thông tư số 116/2026/TT-BCA) hoặc Tờ khai thay đổi thông tin cư trú dùng cho người Việt Nam định cư ở nước ngoài về Việt Nam sinh sống (mẫu CT02 ban hành kèm theo Thông tư số 116/2026/TT-BCA).\nVăn bản đề nghị đăng ký tạm trú, trong đó ghi rõ thông tin về chỗ ở hợp pháp kèm danh sách người tạm trú. Danh sách bao gồm những thông tin cơ bản của từng người: họ, chữ đệm và tên; ngày, tháng, năm sinh; giới tính; số định danh cá nhân và thời hạn tạm trú.\n- Trường hợp giấy tờ, tài liệu chứng minh chỗ ở hợp pháp để đăng ký tạm trú là văn bản cho thuê, cho mượn, cho ở nhờ nhà ở, nhà khác của cá nhân, tổ chức thì văn bản đó không bắt buộc phải công chứng hoặc chứng thực. - Người nước ngoài được nhập quốc tịch Việt Nam khi đăng ký tạm trú lần đầu phải có Quyết định của Chủ tịch nước về việc cho nhập quốc tịch Việt Nam. Người gốc Việt Nam được trở lại quốc tịch Việt Nam khi đăng ký tạm trú lần đầu sau khi được cho trở lại quốc tịch Việt Nam phải có Quyết định của Chủ tịch nước về việc cho trở lại quốc tịch Việt Nam trừ trường hợp đã khai thác được thông tin trong Cơ sở dữ liệu quốc tịch. - Trong thời hạn tối đa 60 ngày kể từ ngày người chưa thành niên được đăng ký khai sinh thì phải thực hiện thủ tục đăng ký cư trú. - Trường hợp công dân không tự thực hiện thủ tục về cư trú thì được ủy quyền cho người khác thực hiện thủ tục về cư trú, trừ trường hợp người giám hộ, người đại diện thực hiện thủ tục về cư trú cho người được giám hộ, người được đại diện thì không phải ủy quyền.\n- Đối với Công an nhân dân: Giấy giới thiệu của Thủ trưởng đơn vị quản lý trực tiếp ghi rõ nội dung để làm thủ tục gia hạn tạm trú và đơn vị có chỗ ở cho cán bộ chiến sĩ (ký tên, đóng dấu).\nĐối với Quân đội nhân dân: Giấy giới thiệu gia hạn tạm trú của đơn vị cấp trung đoàn và tương đương trở lên\n- Văn bản đề nghị gia hạn tạm trú trong đó ghi rõ thông tin về chỗ ở hợp pháp kèm danh sách người gia hạn tạm trú. Danh sách bao gồm những thông tin cơ bản của từng người: họ, chữ đệm và tên; ngày, tháng, năm sinh; giới tính; số định danh cá nhân và thời hạn tạm trú.\nTrường hợp công dân không tự thực hiện thủ tục về cư trú thì được ủy quyền cho người khác thực hiện thủ tục về cư trú, trừ trường hợp người giám hộ, người đại diện thực hiện thủ tục về cư trú cho người được giám hộ, người được đại diện thì không phải ủy quyền.\nThông tin chứng minh thuộc trường hợp xóa đăng ký tạm trú của công dân theo quy định tại điểm c, e, g, h khoản 1 Điều 29 Luật Cư trú trong Cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành và cơ sở dữ liệu khác được kết nối, chia sẻ với cơ quan đăng ký cư trú. Trường hợp thông tin chưa được kết nối, chia sẻ thì công dân xuất trình giấy tờ, tài liệu chứng minh thuộc một trong các trường hợp xóa đăng ký tạm trú theo quy định tại điểm c, e, g, h khoản 1 Điều 29 Luật Cư trú", "thoi_han_le_phi": "Thủ tục: Đăng ký tạm trú. Cơ quan có thẩm quyền giải quyết: Bộ Công an. Thời hạn giải quyết: DIRECT: a) Đối với trường hợp “Đăng ký tạm trú”, “Gia hạn tạm trú”\n- Đăng ký tạm trú, gia hạn tạm trú (cá nhân, hộ gia đình):\n+ Trường hợp công dân nộp hồ sơ trực tiếp thu 15.000 đồng/lần đăng ký.\n- Đăng ký tạm trú theo danh sách, gia hạn tạm trú theo danh sách:\n+ Trường hợp công dân nộp hồ sơ trực tiếp thu 10.000 đồng/người/lần đăng ký.\nb) Đối với trường hợp “Xóa đăng ký tạm trú” \nKhông thu lệ phí. | ONLINE: a) Đối với trường hợp “Đăng ký tạm trú”, “Gia hạn tạm trú”\n- Đăng ký tạm trú, gia hạn tạm trú (cá nhân, hộ gia đình):\n+ Trường hợp công dân nộp hồ sơ qua Cổng dịch vụ công quốc gia thu 7.000 đồng/lần đăng ký.\n- Đăng ký tạm trú theo danh sách, gia hạn tạm trú theo danh sách:\n+ Trường hợp công dân nộp hồ sơ qua Cổng dịch vụ công quốc gia thu 5.000 đồng/người/lần đăng ký.\n- Công dân nộp hồ sơ qua Ứng dụng định danh quốc gia từ ngày 01/4/2026 đến 31/12/2026 thì được miễn lệ phí.\n- Công dân thuộc diện được miễn phí theo quy định tại Điều 4 Thông tư số 75/2022/TT-BTC ngày 22/12/2022 quy định mức thu, chế độ thu, nộp và quản lý lệ phí đăng ký cư trú được sửa đổi, bổ sung tại Thông tư số 71/2025/TT-BTC ngày 01/7/2025 của Bộ trưởng Bộ Tài chính thì công dân phải xuất trình giấy tờ chứng minh thuộc diện được miễn trừ trường hợp thông tin đã có trong Cơ sở dữ liệu quốc gia về dân cư hoặc Cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành mà đã được kết nối với Cơ sở dữ liệu quốc gia về dân cư.\nb) Đối với trường hợp “Xóa đăng ký tạm trú” \nKhông thu lệ phí.. Mức phí/lệ phí: Đăng ký tạm trú, gia hạn tạm trú (cá nhân, hộ gia đình): Trường hợp công dân nộp hồ sơ qua Cổng dịch vụ công quốc gia thu 7.000 đồng/lần đăng ký.. – Đăng ký tạm trú, gia hạn tạm trú (cá nhân, hộ gia đình): Trường hợp công dân nộp hồ sơ qua Cổng dịch vụ công quốc gia thu 7.000 đồng/lần đăng ký.", "can_cu_phap_ly": "116/2026/TT-BCA\n54/2025/TT-BCA\n154/2024/NĐ-CP\n66.7/2025/NQ-CP\n68/2020/QH14\n75/2022/TT-BTC\n29/2026/TT-BTC\n190/2021/TT-BQP"}'),
('TTHC-CR-04', '1.000039', 'Thủ tục gia hạn tạm trú, cấp thị thực mới cho người nước ngoài đang tạm trú ở Việt Nam tại cơ quan có thẩm quyền ở trong nước của Bộ Ngoại giao', 'Cư trú', '- Cơ quan có thẩm quyền giải quyết: Bộ Ngoại giao
- Cơ quan trực tiếp thực hiện: Bộ phận Tiếp nhận và Trả kết quả (Một cửa) cấp Xã/Phường.', 'Thủ tục: Thủ tục gia hạn tạm trú, cấp thị thực mới cho người nước ngoài đang tạm trú ở Việt Nam tại cơ quan có thẩm quyền ở trong nước của Bộ Ngoại giao. Cơ quan có thẩm quyền giải quyết: Bộ Ngoại giao. Thời hạn giải quyết: POSTAL: Lưu ý: thời gian xử lý hồ sơ được áp dụng theo nguyên tắc có đi có lại, phù hợp với Luật Xuất nhập cảnh 2014 | DIRECT: Lưu ý: thời gian xử lý hồ sơ được áp dụng theo nguyên tắc có đi có lại, phù hợp với Luật Xuất nhập cảnh 2014. Mức phí/lệ phí: Loại có giá trị trên 6 tháng đến 01 năm.', 'Loại có giá trị trên 6 tháng đến 01 năm', 'https://dichvucong.gov.vn (API ID: 019d2bf9-e9b9-754f-b246-98f868065e48)', '{"trinh_tu": "Bước 1: Tổ chức, cá nhân chuẩn bị hồ sơ theo quy định và nộp hồ sơ tại Bộ phận tiếp nhận.\nBộ phận tiếp nhận bao gồm:\n- Bộ phận Một cửa của Bộ Ngoại giao tại 40 Trần Phú, Ba Đình, Thành phố Hà Nội;\n- Sở Ngoại vụ Thành phố Hồ Chí Minh tại số 6 Alexandre De Rhodes, Quận 1, Thành phố Hồ Chí Minh.\nBước 2: Bộ phận tiếp nhận kiểm tra tính hợp lệ, đầy đủ của hồ sơ:\n- Trường hợp hồ sơ không thuộc phạm vi giải quyết, Bộ phận tiếp nhận hướng dẫn tổ chức, cá nhân liên hệ với cơ quan có thẩm quyền để giải quyết theo quy định.\n- Trường hợp hồ sơ chưa hợp lệ, chưa đầy đủ, Bộ phận tiếp nhận hướng dẫn tổ chức, cá nhân bổ sung, hoàn thiện hồ sơ theo quy định và trả lại hồ sơ kèm “Phiếu yêu cầu bổ sung, hoàn thiện hồ sơ”. Việc yêu cầu bổ sung, hoàn\nthiện hồ sơ phải cụ thể, đầy đủ một lần để tổ chức, cá nhân bổ sung đầy đủ, chính xác. Thời hạn giải quyết TTHC được tính từ ngày hồ sơ được bổ sung, hoàn thiện đầy đủ theo quy định.\n- Trường hợp hồ sơ không đủ điều kiện giải quyết theo quy định, Bộ phận tiếp nhận từ chối nhận hồ sơ và trả lại hồ sơ kèm “Phiếu từ chối tiếp nhận giải quyết hồ sơ” cho tổ chức, cá nhân.\n- Trường hợp hồ sơ hợp lệ, đủ điều kiện giải quyết, Bộ phận tiếp nhận tiến hành nhận hồ sơ, in “Giấy tiếp nhận hồ sơ và hẹn trả kết quả” và chuyển hồ sơ đến Đơn vị chuyên môn để giải quyết theo thẩm quyền.\nBước 3: Đơn vị chuyên môn giải quyết và trả kết quả cho Bộ phận tiếp nhận theo quy định:\n- Trường hợp hồ sơ phải bổ sung, hoàn thiện theo quy định, Đơn vị chuyên môn phải thông báo bằng văn bản, ghi rõ lý do, nội dung cần bổ sung theo mẫu “Phiếu yêu cầu bổ sung, hoàn thiện hồ sơ” để gửi cho tổ chức, cá nhân thông qua Bộ phận tiếp nhận. Việc yêu cầu bổ sung, hoàn thiện hồ sơ chỉ được thực hiện một (01) lần. Thời hạn giải quyết TTHC được tính lại từ đầu, sau khi nhận đầy đủ hồ sơ.\n- Trường hợp không thể trả kết quả đúng thời hạn hoặc hồ sơ phải xin ý kiến của cấp/cơ quan có thẩm quyền liên quan, Đơn vị chuyên môn phải thông báo bằng văn bản cho Bộ phận tiếp nhận và gửi văn bản xin lỗi tổ chức, cá nhân, trong đó ghi rõ lý do quá hạn và thời gian sẽ trả kết quả theo mẫu “Phiếu xin lỗi và hẹn lại ngày trả kết quả”. Việc hẹn lại ngày trả kết quả được thực hiện không quá một (01) lần.\n- Trường hợp hồ sơ không đủ điều kiện giải quyết, Đơn vị chuyên môn trả lại hồ sơ, kèm văn bản nêu rõ lý do không giải quyết hồ sơ theo mẫu “Phiếu từ chối tiếp nhận giải quyết hồ sơ” để gửi cho tổ chức, cá nhân thông qua Bộ phận\ntiếp nhận.\n- Trường hợp hồ sơ đủ điều kiện giải quyết, Đơn vị chuyên môn giải quyết và trả kết quả cho Bộ phận tiếp nhận đúng thời gian quy định.\nBước 4: Sau khi nhận kết quả giải quyết TTHC từ Đơn vị chuyên môn, Bộ phận tiếp nhận kiểm tra lại các thông tin và trả kết quả cho tổ chức, cá nhân.\nTrường hợp hồ sơ không đủ điều kiện giải quyết, Bộ phận tiếp nhận giải thích rõ cho tổ chức, cá nhân về lý do từ chối giải quyết hồ sơ theo nội dung trong “Phiếu từ chối tiếp nhận giải quyết hồ sơ” của Đơn vị chuyên môn.", "co_quan_thuc_hien": "- Cơ quan có thẩm quyền giải quyết: Bộ Ngoại giao\n- Cơ quan trực tiếp thực hiện: Bộ phận Tiếp nhận và Trả kết quả (Một cửa) cấp Xã/Phường.", "thanh_phan_ho_so": "Tờ khai đề nghị cấp thị thực, gia hạn tạm trú theo mẫu NA5 ban hành kèm theo Thông tư 04/2015/TT-BCA ngày 05/01/2015 của Bộ trưởng Bộ Công an quy định mẫu giấy tờ liên quan đến việc nhập cảnh, xuất cảnh, cư trú của người nước ngoài tại Việt Nam", "thoi_han_le_phi": "Thủ tục: Thủ tục gia hạn tạm trú, cấp thị thực mới cho người nước ngoài đang tạm trú ở Việt Nam tại cơ quan có thẩm quyền ở trong nước của Bộ Ngoại giao. Cơ quan có thẩm quyền giải quyết: Bộ Ngoại giao. Thời hạn giải quyết: POSTAL: Lưu ý: thời gian xử lý hồ sơ được áp dụng theo nguyên tắc có đi có lại, phù hợp với Luật Xuất nhập cảnh 2014 | DIRECT: Lưu ý: thời gian xử lý hồ sơ được áp dụng theo nguyên tắc có đi có lại, phù hợp với Luật Xuất nhập cảnh 2014. Mức phí/lệ phí: Loại có giá trị trên 6 tháng đến 01 năm. – Loại có giá trị trên 6 tháng đến 01 năm", "can_cu_phap_ly": "04/2016/TT-BNG\n219/2016/TT-BTC"}'),
('TTHC-CR-06', '2.001159', 'Thông báo lưu trú', 'Cư trú', '- Cơ quan có thẩm quyền tiếp nhận & giải quyết: Công an cấp xã (ngành dọc Bộ Công an).
- Kênh nộp: Trực tiếp tại Công an cấp xã hoặc trực tuyến qua ứng dụng VNeID / Cổng Dịch vụ công Bộ Công an (không nộp vào hàng đợi duyệt của UBND xã).', 'Thủ tục: Thông báo lưu trú. Cơ quan có thẩm quyền giải quyết: Bộ Công an. Thời hạn giải quyết: ONLINE: - Thông qua số điện thoại, trang thông tin điện tử của cơ quan đăng ký cư trú hoặc hộp thư điện tử do cơ quan đăng ký cư trú thông báo hoặc niêm yết.
- Thông qua Cổng dịch vụ công quốc gia, Ứng dụng định danh quốc gia.
- Thông qua phần mềm thông báo lưu trú.. Mức phí/lệ phí: Theo quy định của HĐND cấp tỉnh/thành phố.', 'Theo quy định của HĐND cấp tỉnh/thành phố', 'https://dichvucong.gov.vn (API ID: 019d2bf7-adb7-7329-8d7c-db89ef073ced)', '{"trinh_tu": "Bước 1: Cá nhân, tổ chức thông báo lưu trú tới cơ quan đăng ký cư trú.\n Bước 2: Cán bộ công an thực hiện tiếp nhận thông báo lưu trú.", "co_quan_thuc_hien": "- Cơ quan có thẩm quyền tiếp nhận & giải quyết: Công an cấp xã (ngành dọc Bộ Công an).\n- Kênh nộp: Trực tiếp tại Công an cấp xã hoặc trực tuyến qua ứng dụng VNeID / Cổng Dịch vụ công Bộ Công an (không nộp vào hàng đợi duyệt của UBND xã).", "thanh_phan_ho_so": "Khi có người đến lưu trú, đại diện hộ gia đình, cơ sở khám bệnh, chữa bệnh, cơ sở lưu trú du lịch, cơ sở lưu trú ở khu công nghiệp, cơ sở khác có chức năng lưu trú thì phải thực hiện việc thông báo lưu trú cho người đang lưu trú theo một trong các hình thức đã được quy định tại và theo quy định sau đây: - Chủ hộ hoặc thành viên hộ gia đình, đại diện cơ sở lưu trú ở khu công nghiệp, cơ sở lưu trú du lịch đề nghị người đến lưu trú xuất trình một trong các giấy tờ pháp lý thể hiện thông tin về số định danh cá nhân theo quy định của pháp luật và thực hiện việc thông báo lưu trú với cơ quan đăng ký cư trú; - Đại diện cơ sở khám bệnh, chữa bệnh có trách nhiệm lập danh sách người đến điều trị nội trú và thực hiện thông báo lưu trú với cơ quan đăng ký cư trú nơi đặt trụ sở cơ sở khám chữa bệnh", "thoi_han_le_phi": "Thủ tục: Thông báo lưu trú. Cơ quan có thẩm quyền giải quyết: Bộ Công an. Thời hạn giải quyết: ONLINE: - Thông qua số điện thoại, trang thông tin điện tử của cơ quan đăng ký cư trú hoặc hộp thư điện tử do cơ quan đăng ký cư trú thông báo hoặc niêm yết.\n- Thông qua Cổng dịch vụ công quốc gia, Ứng dụng định danh quốc gia.\n- Thông qua phần mềm thông báo lưu trú.. Mức phí/lệ phí: Theo quy định của HĐND cấp tỉnh/thành phố. – Theo quy định của HĐND cấp tỉnh/thành phố", "can_cu_phap_ly": "68/2020/QH14\n116/2026/TT-BCA\n54/2025/TT-BCA\n154/2024/NĐ-CP"}'),
('TTHC-CR-07', '1.003677', 'Khai báo tạm vắng', 'Cư trú', '- Cơ quan có thẩm quyền tiếp nhận & giải quyết: Công an cấp xã (ngành dọc Bộ Công an).
- Kênh nộp: Trực tiếp tại Công an cấp xã hoặc trực tuyến qua ứng dụng VNeID / Cổng Dịch vụ công Bộ Công an (không nộp vào hàng đợi duyệt của UBND xã).', 'Thủ tục: Khai báo tạm vắng. Cơ quan có thẩm quyền giải quyết: Bộ Công an. Thời hạn giải quyết: ONLINE: Trong thời hạn 01 ngày làm việc kể từ khi tiếp nhận đề nghị khai báo tạm vắng của công dân; trường hợp phức tạp thì có thể kéo dài hơn nhưng không quá 02 ngày làm việc. | DIRECT: Trong thời hạn 01 ngày làm việc kể từ khi tiếp nhận đề nghị khai báo tạm vắng của công dân; trường hợp phức tạp thì có thể kéo dài hơn nhưng không quá 02 ngày làm việc.. Mức phí/lệ phí: Theo quy định của HĐND cấp tỉnh/thành phố.', 'Theo quy định của HĐND cấp tỉnh/thành phố', 'https://dichvucong.gov.vn (API ID: 019d2bf7-6f56-704f-95b8-8d949272c6ad)', '{"trinh_tu": "Bước 1: Cá nhân, tổ chức chuẩn bị hồ sơ theo quy định của pháp luật.\nBước 2: Cá nhân, tổ chức nộp hồ sơ đến Công an cấp xã.\nBước 3: Khi tiếp nhận hồ sơ khai báo tạm vắng trong Cơ sở dữ liệu về cư trú, cơ quan đăng ký cư trú kiểm tra tính pháp lý và nội dung hồ sơ:\n- Trường hợp hồ sơ đã đầy đủ, chính xác theo quy định thì cán bộ đăng ký tiếp nhận hồ sơ và cấp Phiếu tiếp nhận hồ sơ và hẹn trả kết quả (mẫu CT04 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký.\n- Trường hợp hồ sơ chưa đầy đủ, chưa chính xác theo quy định thì cán bộ đăng ký trả lại hồ sơ và cấp Phiếu thông báo về việc giải quyết hồ sơ cư trú (mẫu CT06 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký; ghi rõ lý do trả lại và hướng dẫn chi tiết, cụ thể cho công dân.\nBước 4: Căn cứ theo ngày hẹn trên Phiếu tiếp nhận hồ sơ và hẹn trả kết quả để nhận thông báo kết quả giải quyết thủ tục đăng ký cư trú (nếu có).", "co_quan_thuc_hien": "- Cơ quan có thẩm quyền tiếp nhận & giải quyết: Công an cấp xã (ngành dọc Bộ Công an).\n- Kênh nộp: Trực tiếp tại Công an cấp xã hoặc trực tuyến qua ứng dụng VNeID / Cổng Dịch vụ công Bộ Công an (không nộp vào hàng đợi duyệt của UBND xã).", "thanh_phan_ho_so": "+ Đề nghị khai báo tạm vắng;\n+ Văn bản đồng ý của cơ quan có thẩm quyền giám sát, quản lý, giáo dục người đó.\nNội dung khai báo tạm vắng gồm: họ và tên, số định danh cá nhân hoặc số Chứng minh nhân dân, số hộ chiếu của người khai báo tạm vắng; lý do tạm vắng; thời gian tạm vắng; địa chỉ nơi đến.", "thoi_han_le_phi": "Thủ tục: Khai báo tạm vắng. Cơ quan có thẩm quyền giải quyết: Bộ Công an. Thời hạn giải quyết: ONLINE: Trong thời hạn 01 ngày làm việc kể từ khi tiếp nhận đề nghị khai báo tạm vắng của công dân; trường hợp phức tạp thì có thể kéo dài hơn nhưng không quá 02 ngày làm việc. | DIRECT: Trong thời hạn 01 ngày làm việc kể từ khi tiếp nhận đề nghị khai báo tạm vắng của công dân; trường hợp phức tạp thì có thể kéo dài hơn nhưng không quá 02 ngày làm việc.. Mức phí/lệ phí: Theo quy định của HĐND cấp tỉnh/thành phố. – Theo quy định của HĐND cấp tỉnh/thành phố", "can_cu_phap_ly": "154/2024/NĐ-CP\n68/2020/QH14\n116/2026/TT-BCA\n54/2025/TT-BCA"}'),
('TTHC-CR-08', '1.010041', 'Xác nhận thông tin về cư trú', 'Cư trú', '- Cơ quan có thẩm quyền tiếp nhận & giải quyết: Công an cấp xã (ngành dọc Bộ Công an).
- Kênh nộp: Trực tiếp tại Công an cấp xã hoặc trực tuyến qua ứng dụng VNeID / Cổng Dịch vụ công Bộ Công an (không nộp vào hàng đợi duyệt của UBND xã).', 'Thủ tục: Xác nhận thông tin về cư trú. Cơ quan có thẩm quyền giải quyết: Bộ Công an. Thời hạn giải quyết: ONLINE: Trong thời hạn 1/2 ngày làm việc kể từ ngày tiếp nhận được hồ sơ đầy đủ, chính xác với trường hợp thông tin cần xác nhận đã có trong Cơ sở dữ liệu quốc gia về dân cư. | ONLINE: Trường hợp thông tin cần xác nhận không có trong Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu về cư trú cần xác minh thì thời hạn giải quyết không quá 03 ngày làm việc.. Mức phí/lệ phí: Miễn phí / Không thu lệ phí.', 'Miễn phí / Không thu lệ phí', 'https://dichvucong.gov.vn (API ID: 019d2bf7-7f19-762d-be5e-741f71796016)', '{"trinh_tu": "Bước 1: Cá nhân, tổ chức chuẩn bị hồ sơ theo quy định của pháp luật.\n Bước 2: Cá nhân, tổ chức nộp hồ sơ đến Công an cấp xã.\n Bước 3: Khi tiếp nhận hồ sơ xác nhận thông tin về cư trú, cơ quan đăng ký cư trú kiểm tra tính pháp lý và nội dung hồ sơ:\n- Trường hợp hồ sơ đã đầy đủ, chính xác theo quy định thì cán bộ đăng ký tiếp nhận hồ sơ và cấp Phiếu tiếp nhận hồ sơ và hẹn trả kết quả (mẫu CT04 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký.\n- Trường hợp hồ sơ chưa đầy đủ, chưa chính xác theo quy định thì cán bộ đăng ký trả lại hồ sơ và cấp Phiếu thông báo về việc giải quyết hồ sơ cư trú (mẫu CT06 ban hành kèm theo Thông tư số 116/2026/TT-BCA) cho người đăng ký; ghi rõ lý do trả lại và hướng dẫn chi tiết, cụ thể cho công dân.\nBước 4: Căn cứ theo ngày hẹn trên Phiếu tiếp nhận hồ sơ và hẹn trả kết quả để nhận thông báo kết quả giải quyết thủ tục đăng ký cư trú (nếu có).", "co_quan_thuc_hien": "- Cơ quan có thẩm quyền tiếp nhận & giải quyết: Công an cấp xã (ngành dọc Bộ Công an).\n- Kênh nộp: Trực tiếp tại Công an cấp xã hoặc trực tuyến qua ứng dụng VNeID / Cổng Dịch vụ công Bộ Công an (không nộp vào hàng đợi duyệt của UBND xã).", "thanh_phan_ho_so": "Tờ khai thay đổi thông tin cư trú (mẫu CT01 ban hành kèm theo Thông tư số 116/2026/TT-BCA).\n- Công dân khai báo thông tin theo biểu mẫu điện tử được cung cấp sẵn, không đính kèm biểu mẫu CT01. - Xác nhận thông tin về cư trú có thể cấp cho cá nhân hoặc cho hộ gia đình: + Trường hợp cấp cho hộ gia đình phải do chủ hộ đề xuất, trường hợp thành viên hộ gia đình đề xuất thì phải có ủy quyền hoặc đồng ý của chủ hộ trừ trường hợp chủ hộ chết, mất tích, không đủ năng lực hành vi dân sự hoặc đang chấp hành án phạt tù thì phải có ý kiến của các thành viên khác đủ năng lực hành vi dân sự trong hộ gia đình. + Trường hợp cá nhân đề nghị không cần chủ hộ đồng ý, trong đó công dân được cung cấp đầy đủ thông tin có liên quan đến hộ gia đình trong giai đoạn công dân là thành viên của hộ gia đình đó. - Trường hợp công dân không tự thực hiện thủ tục thì được ủy quyền cho người khác thực hiện, trừ trường hợp người giám hộ, người đại diện thực hiện thủ tục về cư trú cho người được giám hộ, người được đại diện thì không phải ủy quyền.", "thoi_han_le_phi": "Thủ tục: Xác nhận thông tin về cư trú. Cơ quan có thẩm quyền giải quyết: Bộ Công an. Thời hạn giải quyết: ONLINE: Trong thời hạn 1/2 ngày làm việc kể từ ngày tiếp nhận được hồ sơ đầy đủ, chính xác với trường hợp thông tin cần xác nhận đã có trong Cơ sở dữ liệu quốc gia về dân cư. | ONLINE: Trường hợp thông tin cần xác nhận không có trong Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu về cư trú cần xác minh thì thời hạn giải quyết không quá 03 ngày làm việc.. Mức phí/lệ phí: Miễn phí / Không thu lệ phí. – Miễn phí / Không thu lệ phí", "can_cu_phap_ly": "68/2020/QH14\n154/2024/NĐ-CP\n116/2026/TT-BCA\n54/2025/TT-BCA"}'),
('TTHC-CR-09', '1.117007', 'Xác nhận của Ủy ban nhân dân cấp xã nơi hộ gia đình cư trú về việc hộ gia đình đang gặp khó khăn về kinh tế', 'Cư trú', '- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).
- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.', 'Thủ tục: Xác nhận của Ủy ban nhân dân cấp xã nơi hộ gia đình cư trú về việc hộ gia đình đang gặp khó khăn về kinh tế. Cơ quan có thẩm quyền giải quyết: Bộ Công an. Thời hạn giải quyết: DIRECT: Thực hiện ngay trong quá trình lập hồ sơ đề nghị chi từ Quỹ của Cơ quan đầu mối. Mức phí/lệ phí: Theo quy định của HĐND cấp tỉnh/thành phố.', 'Theo quy định của HĐND cấp tỉnh/thành phố', 'https://dichvucong.gov.vn (API ID: 01a11463-3eeb-776b-a646-9a9f0b5bb740)', '{"trinh_tu": "- Bước 1: Cơ quan đầu mối phối hợp với Ủy ban nhân dân cấp xã, các cơ quan, tổ chức liên quan xác minh hoàn cảnh khó khăn về kinh tế.\n\n- Bước 2: Xác nhận của Ủy ban nhân dân cấp xã nơi nạn nhân cư trú hoặc cơ quan, tổ chức nơi nạn nhân học tập, làm việc về việc nạn nhân hoặc gia đình của nạn nhân đang gặp khó khăn về kinh tế đối với trường hợp nạn nhân bị thương trong vụ tai nạn giao thông đường bộ với tỷ lệ tổn thương cơ thể trên 31% đến dưới 81% đang gặp khó khăn về kinh tế hoặc xác nhận của Ủy ban nhân dân cấp xã nơi hộ gia đình cư trú về việc hộ gia đình đang gặp khó khăn về kinh tế đối với trường hợp hộ gia đình có nạn nhân bị chết trong vụ tai nạn giao thông đường bộ đang gặp khó khăn về kinh tế.", "co_quan_thuc_hien": "- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).\n- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.", "thanh_phan_ho_so": "Xác nhận của Ủy ban nhân dân cấp xã nơi nạn nhân, hộ gia đình nạn nhân cư trú hoặc của cơ quan, tổ chức nơi nạn nhân học tập, làm việc", "thoi_han_le_phi": "Thủ tục: Xác nhận của Ủy ban nhân dân cấp xã nơi hộ gia đình cư trú về việc hộ gia đình đang gặp khó khăn về kinh tế. Cơ quan có thẩm quyền giải quyết: Bộ Công an. Thời hạn giải quyết: DIRECT: Thực hiện ngay trong quá trình lập hồ sơ đề nghị chi từ Quỹ của Cơ quan đầu mối. Mức phí/lệ phí: Theo quy định của HĐND cấp tỉnh/thành phố. – Theo quy định của HĐND cấp tỉnh/thành phố", "can_cu_phap_ly": "126/2026/TT-BCA"}'),
('TTHC-CR-10', '2.002516', 'Thủ tục xác nhận thông tin hộ tịch', 'Hộ tịch', '- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).
- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.', 'Thủ tục: Thủ tục xác nhận thông tin hộ tịch. Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: ONLINE: Trực tiếp thực hiện hoặc ủy quyền cho người khác thực hiện nộp hồ sơ | POSTAL: Trực tiếp thực hiện hoặc ủy quyền cho người khác thực hiện nộp hồ sơ | DIRECT: Trực tiếp thực hiện hoặc ủy quyền cho người khác thực hiện nộp hồ sơ. Mức phí/lệ phí: 8.000 đồng/Văn bản xác nhận về một việc hộ tịch của cá nhân đã đăng ký.Miễn lệ phí cho người thuộc gia đình có công với cách mạng; người thuộc hộ nghèo; người khuyết tật..', '8.000 đồng/Văn bản xác nhận về một việc hộ tịch của cá nhân đã đăng ký.Miễn lệ phí cho người thuộc gia đình có công với cách mạng; người thuộc hộ nghèo; người khuyết tật.', 'https://dichvucong.gov.vn (API ID: 019d2bfd-a586-71fe-8c10-836e09f0a879)', '{"trinh_tu": "- Nếu lựa chọn hình thức nộp hồ sơ trực tiếp, người yêu cầu cấp xác nhận thông tin hộ tịch nộp hồ sơ đề nghị cấp xác nhận thông tin hộ tịch tại Trung tâm Phục vụ hành chính công có thẩm quyền; nộp phí theo quy định pháp luật. \n- Nếu lựa chọn hình thức nộp hồ sơ trực tuyến, người yêu cầu cấp xác nhận thông tin hộ tịch truy cập Cổng dịch vụ công quốc gia hoặc Ứng dụng định danh quốc gia.\nNgười yêu cầu cấp xác nhận thông tin hộ tịch trực tuyến cung cấp thông tin theo mẫu điện tử tương tác đề nghị xác nhận thông tin hộ tịch , đính kèm bản chụp hoặc bản sao điện tử các giấy tờ, tài liệu liên quan đến nội dung đề nghị xác nhận thông tin hộ tịch; nộp phí thông qua chức năng thanh toán trực tuyến hoặc bằng cách thức khác theo quy định pháp luật, hoàn tất việc nộp hồ sơ.\n- Cán bộ tiếp nhận hồ sơ tại Trung tâm Phục vụ hành chính công có trách nhiệm kiểm tra tính chính xác, đầy đủ, thống nhất, hợp lệ của hồ sơ. \n(i) Trường hợp hồ sơ đầy đủ, hợp lệ thì tiếp nhận hồ sơ, có Phiếu hẹn, trả kết quả cho người yêu cầu (nếu người yêu cầu nộp hồ sơ trực tiếp) hoặc gửi ngay Phiếu hẹn, trả kết quả qua thư điện tử hoặc gửi tin nhắn hẹn trả kết quả qua điện thoại di động cho người yêu cầu (nếu người yêu cầu nộp hồ sơ trực tuyến), đồng thời chuyển hồ sơ để công chức tư pháp - hộ tịch xử lý; trường hợp tiếp nhận hồ sơ tại Trung tâm Phục vụ hành chính công cấp tỉnh, cán bộ tiếp nhận hồ sơ chuyển hồ sơ đến Sở Tư pháp/Ủy ban nhân dân cấp xã có thẩm quyền xử lý. \n(ii) Trường hợp hồ sơ chưa đầy đủ, hợp lệ thì cán bộ tiếp nhận hồ sơ thông báo cho người yêu cầu bổ sung, hoàn thiện hồ sơ, nêu rõ loại giấy tờ, nội dung cần bổ sung để người yêu cầu bổ sung, hoàn thiện. Sau khi hồ sơ được bổ sung, thực hiện lại bước (i);\n(iii) Trường hợp người yêu cầu cấp xác nhận thông tin hộ tịch không bổ sung, hoàn thiện được hồ sơ thì cán bộ tiếp nhận hồ sơ báo cáo Lãnh đạo Trung tâm Phục vụ hành chính công có thông báo từ chối giải quyết yêu cầu xác nhận thông tin hộ tịch.\n- Công chức tư pháp - hộ tịch/người làm công tác hộ tịch thẩm tra hồ sơ (thẩm tra tính thống nhất, hợp lệ của các thông tin trong hồ sơ, giấy tờ, tài liệu do người yêu cầu nộp, xuất trình hoặc đính kèm).\n+ Trường hợp hồ sơ cần bổ sung, hoàn thiện hoặc không đủ điều kiện giải quyết, phải từ chối thì công chức tư pháp - hộ tịch/người làm công tác hộ tịch gửi thông báo về tình trạng hồ sơ tới Trung tâm Phục vụ hành chính công để thông báo cho người nộp hồ sơ – thực hiện lại bước (ii) hoặc (iii);\n+ Trường hợp cần phải kiểm tra, xác minh làm rõ hoặc do nguyên nhân khác mà không thể trả kết quả đúng thời gian đã hẹn thì công chức tư pháp - hộ tịch/người làm công tác hộ tịch lập Phiếu xin lỗi và hẹn lại ngày trả kết quả, trong đó nêu rõ lý do chậm trả kết quả và thời gian hẹn trả kết quả, chuyển Trung tâm Phục vụ hành chính công để trả cho người yêu cầu (nếu người yêu cầu nộp hồ sơ trực tiếp), hoặc gửi Phiếu xin lỗi và hẹn lại ngày trả kết quả qua thư điện tử hoặc gửi tin nhắn qua điện thoại di động cho người yêu cầu (nếu người yêu cầu nộp hồ sơ trực tuyến).\nTrường hợp cần xác minh, công chức giải quyết hồ sơ báo cáo Thủ trưởng Cơ quan quản lý Cơ sở dữ liệu hộ tịch điện tử có văn bản đề nghị cơ quan công an, các cơ quan khác có liên quan xác minh theo quy định tại Khoản 3 Điều 13 Nghị định số 87/2020/NĐ-CP. Trường hợp kết quả xác minh không có thông tin hoặc thông tin không thống nhất với giấy tờ người yêu cầu cung cấp thì từ chối cấp Văn bản xác nhận thông tin hộ tịch. \nĐối với yêu cầu xác nhận thông tin hộ tịch của cá nhân, nếu thấy thông tin hộ tịch của cá nhân không có sự thay đổi thì công chức giải quyết hồ sơ báo cáo Thủ trưởng Cơ quan quản lý Cơ sở dữ liệu hộ tịch điện tử không cấp Văn bản xác nhận thông tin hộ tịch mà hướng dẫn người yêu cầu làm thủ tục cấp bản sao Giấy khai sinh hoặc bản sao trích lục hộ tịch tương ứng, trừ trường hợp cơ quan, tổ chức có thẩm quyền đề nghị cấp văn bản xác nhận để giải quyết vụ việc liên quan đến cá nhân.\n+ Nếu thấy hồ sơ đầy đủ, hợp lệ, đúng quy định, thông tin trong Cơ sở dữ liệu hộ tịch điện tử và thông tin đề nghị xác nhận là đúng, trường hợp tiếp nhận hồ sơ cấp xác nhận thông tin hộ tịch theo hình thức trực tiếp, thì công chức giải quyết hồ sơ in Văn bản xác nhận thông tin hộ tịch, trình Thủ trưởng Cơ quan quản lý Cơ sở dữ liệu hộ tịch điện tử ký, chuyển tới Trung tâm Phục vụ hành chính công để trả kết quả cho người yêu cầu.\nTrường hợp tiếp nhận hồ sơ xin cấp xác nhận thông tin hộ tịch theo hình thức trực tuyến, công chức giải quyết hồ sơ gửi lại biểu mẫu Xác nhận thông tin hộ tịch điện tử với thông tin đầy đủ cho người yêu cầu qua thư điện tử hoặc thiết bị số. \nNgười yêu cầu có trách nhiệm kiểm tra tính chính xác, đầy đủ của các thông tin trên biểu mẫu Xác nhận thông tin hộ tịch điện tử và xác nhận (tối đa một ngày).\nNếu người yêu cầu xác nhận thông tin đã thống nhất, đầy đủ hoặc không có phản hồi sau thời hạn một ngày thì công chức giải quyết hồ sơ in Văn bản xác nhận thông tin hộ tịch, trình Thủ trưởng Cơ quan quản lý Cơ sở dữ liệu hộ tịch điện tử ký cấp văn bản xác nhận thông tin hộ tịch, chuyển Trung tâm Phục vụ hành chính công trả kết quả cho người yêu cầu.", "co_quan_thuc_hien": "- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).\n- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.", "thanh_phan_ho_so": "Văn bản ủy quyền (được chứng thực) theo quy định của pháp luật trong trường hợp ủy quyền thực hiện việc xin cấp xác nhận thông tin hộ tịch. Trường hợp người được ủy quyền là ông, bà, cha, mẹ, con, vợ, chồng, anh, chị, em ruột của người ủy quyền thì văn bản ủy quyền không phải chứng thực.\nGiấy tờ, tài liệu có liên quan đến nội dung đề nghị xác nhận thông tin hộ tịch\n- Giấy tờ có giá trị chứng minh thông tin về cư trú trong trường hợp cơ quan đăng ký hộ tịch không thể khai thác được thông tin về nơi cư trú của công dân theo các phương thức quy định tại khoản 2 Điều 14 Nghị định số 104/2022/NĐ-CP ngày 21/12/2022 của Chính phủ. Trường hợp các thông tin về giấy tờ chứng minh nơi cư trú đã được khai thác từ Cơ sở dữ liệu quốc gia về dân cư bằng các phương thức này thì người có yêu cầu không phải xuất trình (theo hình thức trực tiếp) hoặc tải lên (theo hình thức trực tuyến).\nTrường hợp không khai thác được thông tin hoặc thông tin khai thác được không đầy đủ, không chính xác thì cơ quan đăng ký hộ tịch yêu cầu người đi đăng ký hộ tịch xuất trình bản chính giấy tờ để chứng minh, đồng thời đề nghị người đi đăng ký hộ tịch cập nhật, điều chỉnh thông tin trong các cơ sở dữ liệu theo quy định của pháp luật.\nTrường hợp giấy tờ tùy thân sử dụng là: Hộ chiếu, Thẻ căn cước, Căn cước công dân, Giấy chứng nhận căn cước thì người có yêu cầu đăng ký hộ tịch chỉ cần cung cấp thông tin số định danh cá nhân hoặc thông tin về giấy tờ (số, ngày/tháng/năm cấp), cơ quan đăng ký hộ tịch có trách nhiệm tra cứu thông tin thông qua kết nối với Cơ sở dữ liệu hộ tịch điện tử, Cơ sở dữ liệu quốc gia về dân cư hoặc cơ sở dữ liệu khác có liên quan để đối chiếu, khai thác dữ liệu.\n- Trường hợp gửi hồ sơ qua hệ thống bưu chính thì phải gửi kèm theo bản sao có chứng thực các giấy tờ phải xuất trình nêu trên.\nTrường hợp các thông tin cá nhân trong các giấy tờ này đã có trong Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu hộ tịch điện tử, được hệ thống điền tự động thì không phải tải lên (theo hình thức trực tuyến)\n- Hộ chiếu/Thẻ căn cước công dân/Thẻ căn cước/Căn cước điện tử/Giấy chứng nhận căn cước hoặc các giấy tờ khác có dán ảnh và thông tin cá nhân do cơ quan có thẩm quyền cấp, còn giá trị sử dụng (sau đây gọi tắt là giấy tờ tùy thân) để chứng minh về nhân thân khi làm thủ tục trực tiếp tại cơ quan đăng ký hộ tịch.\n+ Người yêu cầu đăng ký hộ tịch có thể nộp bản sao được chứng thực từ bản chính hoặc bản sao được cấp từ sổ gốc (sau đây gọi là bản sao) hoặc bản chụp kèm theo bản chính, bản điện tử các giấy tờ này, bao gồm cả giấy tờ được tích hợp, hiển thị trên Ứng dụng định danh điện tử (VneID).\nTrường hợp người yêu cầu nộp bản chụp kèm theo bản chính giấy tờ thì người tiếp nhận có trách nhiệm kiểm tra, đối chiếu bản chụp với bản chính và ký xác nhận, không được yêu cầu nộp bản sao giấy tờ đó.\n- Trường hợp người yêu cầu cấp xác nhận thông tin hộ tịch không cung cấp đầy đủ hoặc cung cấp các thông tin không chính xác, không thể tra cứu được thông tin thì cơ quan đăng ký hộ tịch từ chối giải quyết.\n- Trường hợp người yêu cầu đăng ký hộ tịch không lựa chọn nhận kết quả tại Trung tâm Phục vụ hành chính công thì người yêu cầu đăng ký hộ tịch nộp các giấy tờ là thành phần hồ sơ theo quy định trước khi nhận kết quả.\n- Cá nhân có quyền lựa chọn thực hiện thủ tục hành chính về hộ tịch tại cơ quan đăng ký hộ tịch nơi cư trú; nơi cư trú của cá nhân được xác định theo quy định của pháp luật về cư trú. Trường hợp cá nhân lựa chọn thực hiện thủ tục hành chính về hộ tịch không phải tại Ủy ban nhân dân cấp xã nơi thường trú hoặc nơi tạm trú thì Ủy ban nhân dân cấp xã nơi tiếp nhận yêu cầu có trách nhiệm hỗ trợ người dân nộp hồ sơ đăng ký hộ tịch trực tuyến đến đúng cơ quan có thẩm quyền theo quy định.\n+ Bản chụp các giấy tờ gửi kèm theo hồ sơ cấp xác nhận thông tin hộ tịch trực tuyến phải bảo đảm rõ nét, đầy đủ, toàn vẹn về nội dung, là bản chụp bằng máy ảnh, điện thoại hoặc được chụp, được quét bằng thiết bị điện tử, từ giấy tờ được cấp hợp lệ, còn giá trị sử dụng.\n+ Người tiếp nhận có trách nhiệm tiếp nhận đúng, đủ hồ sơ đăng ký hộ tịch theo quy định của pháp luật hộ tịch, không được yêu cầu người đăng ký hộ tịch nộp thêm giấy tờ mà pháp luật hộ tịch không quy định phải nộp .\n+ Trường hợp giấy tờ, tài liệu phải gửi kèm trong hồ sơ cấp xác nhận thông tin hộ tịch trực tuyến đã có bản sao điện tử hoặc bản điện tử giấy tờ hộ tịch thì người yêu cầu được sử dụng bản điện tử này.\n+ Đối với giấy tờ xuất trình khi đăng ký hộ tịch, người tiếp nhận có trách nhiệm kiểm tra, đối chiếu với thông tin trong tờ khai, chụp lại hoặc ghi lại thông tin để lưu trong hồ sơ và trả lại cho người xuất trình, không được yêu cầu nộp bản sao hoặc bản chụp giấy tờ đó.\n- Đối với giấy tờ gửi kèm theo nếu người yêu cầu nộp hồ sơ theo hình thức trực tuyến:\n- Giấy tờ do cơ quan có thẩm quyền của nước ngoài cấp, công chứng hoặc xác nhận để sử dụng cho việc đăng ký hộ tịch tại Việt Nam phải được hợp pháp hóa lãnh sự theo quy định của pháp luật, trừ trường hợp được miễn theo điều ước quốc tế mà Việt Nam là thành viên.\n- Đối với giấy tờ nộp, xuất trình nếu người yêu cầu nộp hồ sơ theo hình thức trực tiếp:\n+ Trường hợp người yêu cầu đăng ký hộ tịch cung cấp thông tin về giấy tờ hộ tịch của cá nhân đã được đăng ký, cơ quan đăng ký hộ tịch có trách nhiệm tra cứu thông tin trên Hệ thống thông tin giải quyết thủ tục hành chính cấp tỉnh thông qua kết nối với Cơ sở dữ liệu hộ tịch điện tử, CSDLQGVDC. Trường hợp không tra cứu được do không có thông tin trong Cơ sở dữ liệu hộ tịch điện tử, CSDLQGVDC thì cơ quan đăng ký hộ tịch yêu cầu người đi đăng ký hộ tịch nộp/xuất trình giấy tờ liên quan để chứng minh.\n- Trường hợp người yêu cầu đăng k‎ý hộ tịch lựa chọn nhận kết quả tại Trung tâm Phục vụ hành chính công thì người yêu cầu đăng ký hộ tịch phải xuất trình giấy tờ tuỳ thân, nộp các giấy tờ là thành phần hồ sơ theo quy định.\nTờ khai đề nghị xác nhận thông tin hộ tịch theo mẫu (nếu người có yêu cầu lựa chọn nộp hồ sơ theo hình thức trực tiếp)\n- Mẫu điện tử tương tác đề nghị xác nhận thông tin hộ tịch (do người yêu cầu cung cấp thông tin theo hướng dẫn trên Cổng dịch vụ công, nếu người có yêu cầu lựa chọn nộp hồ sơ theo hình thức trực tuyến)\nNgười có yêu cầu xác nhận thông tin hộ tịch thực hiện việc nộp/xuất trình (theo hình thức trực tiếp) hoặc tải lên (theo hình thức trực tuyến) các giấy tờ sau:", "thoi_han_le_phi": "Thủ tục: Thủ tục xác nhận thông tin hộ tịch. Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: ONLINE: Trực tiếp thực hiện hoặc ủy quyền cho người khác thực hiện nộp hồ sơ | POSTAL: Trực tiếp thực hiện hoặc ủy quyền cho người khác thực hiện nộp hồ sơ | DIRECT: Trực tiếp thực hiện hoặc ủy quyền cho người khác thực hiện nộp hồ sơ. Mức phí/lệ phí: 8.000 đồng/Văn bản xác nhận về một việc hộ tịch của cá nhân đã đăng ký.Miễn lệ phí cho người thuộc gia đình có công với cách mạng; người thuộc hộ nghèo; người khuyết tật.. – 8.000 đồng/Văn bản xác nhận về một việc hộ tịch của cá nhân đã đăng ký.Miễn lệ phí cho người thuộc gia đình có công với cách mạng; người thuộc hộ nghèo; người khuyết tật.", "can_cu_phap_ly": "04/2020/TT-BTP\n07/2025/NĐ-CP\n120/2025/NĐ-CP\n66.7/2025/NQ-CP\n60/2014/QH13\n01/2022/TT-BTP\n85/2019/TT-BTC\n104/2022/NĐ-CP\n123/2015/NĐ-CP\n08/2025/TT-BTP\n18/2026/NĐ-CP\n87/2020/NĐ-CP\nThông tư số 03/2023/TT-BTP\n106/2021/TT-BTC\n281/2016/TT-BTC"}'),
('TTHC-CT-01', '1.001606', 'Thủ tục Chứng thực bản sao từ bản chính các giấy tờ, văn bản do cơ quan có thẩm quyền cấp hoặc chứng nhận', 'Chứng thực', '- Cơ quan tiếp nhận: Trung tâm Phục vụ hành chính công cấp xã.
- Thẩm quyền ký: Lãnh đạo UBND cấp xã, hoặc Giám đốc/Phó Giám đốc TTPVHCC cấp xã khi có Quyết định ủy quyền còn hiệu lực (Nghị định 280/2025/NĐ-CP).', 'Thủ tục: Thủ tục Chứng thực bản sao từ bản chính các giấy tờ, văn bản do cơ quan có thẩm quyền cấp hoặc chứng nhận. Cơ quan có thẩm quyền giải quyết: Bộ Ngoại giao. Thời hạn giải quyết: DIRECT: Thời hạn thực hiện yêu cầu chứng thực phải được đảm bảo ngay trong ngày CQĐD tiếp nhận yêu cầu hoặc trong ngày làm việc tiếp theo nếu tiếp nhận yêu cầu sau 15 giờ; trừ trường hợp cùng một lúc yêu cầu chứng thực bản sao từ nhiều loại giấy tờ, văn bản; bản chính có nhiều trang; yêu cầu số lượng nhiều bản sao; nội dung giấy tờ, văn bản phức tạp khó kiểm tra, đối chiếu mà cơ quan, tổ chức thực hiện chứng thực không thể đáp ứng được thời hạn quy định thì thời hạn chứng thực được kéo dài thêm không quá 02 (hai) ngày làm việc hoặc có thể dài hơn theo thỏa thuận bằng văn bản với người yêu cầu chứng thực.. Mức phí/lệ phí: Miễn phí / Không thu lệ phí.', 'Miễn phí / Không thu lệ phí', 'https://dichvucong.gov.vn (API id: 019d2bf9-f18f-72ee-9d48-c87af3909b19)', '{"trinh_tu": "1.2. Cơ quan đại diện tiếp nhận hồ sơ, xem xét giải quyết.\n1.3. Nhận kết quả trực tiếp tại trụ sở cơ quan theo phiếu hẹn hồ sơ.\n\n- Khi tiếp nhận hồ sơ, Cơ quan đại diện cấp phiếu hẹn cho Người yêu cầu chứng nhận giấy tờ, trong đó ghi rõ địa điểm, thời gian tiếp nhận hồ sơ, giấy tờ kèm theo và thời gian trả lời kết quả.", "co_quan_thuc_hien": "- Cơ quan tiếp nhận: Trung tâm Phục vụ hành chính công cấp xã.\n- Thẩm quyền ký: Lãnh đạo UBND cấp xã, hoặc Giám đốc/Phó Giám đốc TTPVHCC cấp xã khi có Quyết định ủy quyền còn hiệu lực (Nghị định 280/2025/NĐ-CP).", "thanh_phan_ho_so": "bản chính giấy tờ, văn bản làm cơ sở để chứng thực bản sao và bản sao cần chứng thực. Trong trường hợp bản chính giấy tờ, văn bản do cơ quan, tổ chức có thẩm quyền của nước ngoài cấp, công chứng hoặc chứng nhận thì phải được hợp pháp hóa lãnh sự theo quy định của pháp luật trước khi yêu cầu chứng thực bản sao; trừ trường hợp được miễn hợp pháp hóa lãnh sự theo điều ước quốc tế mà Việt Nam là thành viên hoặc theo nguyên tắc có đi, có lại.", "thoi_han_le_phi": "Thủ tục: Thủ tục Chứng thực bản sao từ bản chính các giấy tờ, văn bản do cơ quan có thẩm quyền cấp hoặc chứng nhận. Cơ quan có thẩm quyền giải quyết: Bộ Ngoại giao. Thời hạn giải quyết: DIRECT: Thời hạn thực hiện yêu cầu chứng thực phải được đảm bảo ngay trong ngày CQĐD tiếp nhận yêu cầu hoặc trong ngày làm việc tiếp theo nếu tiếp nhận yêu cầu sau 15 giờ; trừ trường hợp cùng một lúc yêu cầu chứng thực bản sao từ nhiều loại giấy tờ, văn bản; bản chính có nhiều trang; yêu cầu số lượng nhiều bản sao; nội dung giấy tờ, văn bản phức tạp khó kiểm tra, đối chiếu mà cơ quan, tổ chức thực hiện chứng thực không thể đáp ứng được thời hạn quy định thì thời hạn chứng thực được kéo dài thêm không quá 02 (hai) ngày làm việc hoặc có thể dài hơn theo thỏa thuận bằng văn bản với người yêu cầu chứng thực.. Mức phí/lệ phí: Miễn phí / Không thu lệ phí. – Miễn phí / Không thu lệ phí", "can_cu_phap_ly": "20/2015/TT-BTP\n23/2015/NĐ-CP\n264/2016/TT-BTC\n33/2009/QH12"}'),
('TTHC-CT-02', '1.001590', 'Thủ tục Chứng thực chữ ký trong các giấy tờ, văn bản', 'Chứng thực', '- Cơ quan tiếp nhận: Trung tâm Phục vụ hành chính công cấp xã.
- Thẩm quyền ký: Lãnh đạo UBND cấp xã, hoặc Giám đốc/Phó Giám đốc TTPVHCC cấp xã khi có Quyết định ủy quyền còn hiệu lực (Nghị định 280/2025/NĐ-CP).', 'Thủ tục: Thủ tục Chứng thực chữ ký trong các giấy tờ, văn bản. Cơ quan có thẩm quyền giải quyết: Bộ Ngoại giao. Thời hạn giải quyết: DIRECT: Thời hạn thực hiện yêu cầu chứng thực phải được bảo đảm ngay trong ngày cơ quan, tổ chức tiếp nhận yêu cầu hoặc trong ngày làm việc tiếp theo, nếu tiếp nhận yêu cầu sau 15 giờ.. Mức phí/lệ phí: Miễn phí / Không thu lệ phí.', 'Miễn phí / Không thu lệ phí', 'https://dichvucong.gov.vn (API ID: 019d2bf9-f195-7038-a176-6bd8019d3d2a)', '{"trinh_tu": "Nộp hồ sơ tại trụ sở Cơ quan đại diện ngoại giao, cơ quan lãnh sự hoặc cơ quan khác được ủy quyền thực hiện chức năng lãnh sự của Việt Nam ở nước ngoài (Cơ quan đại diện).\nCơ quan đại diện thực kiểm tra giấy tờ yêu cầu chứng thực, nếu thấy đủ giấy tờ theo quy định, tại thời điểm chứng thực, người yêu cầu chứng thực minh mẫn, nhận thức và làm chủ được hành vi của mình và việc chứng thực không thuộc các trường hợp không được chứng thực thì yêu cầu người yêu cầu chứng thực ký trước mặt và thực hiện chứng thực.\nNhận kết quả trực tiếp tại trụ sở cơ quan theo phiếu hẹn hồ sơ", "co_quan_thuc_hien": "- Cơ quan tiếp nhận: Trung tâm Phục vụ hành chính công cấp xã.\n- Thẩm quyền ký: Lãnh đạo UBND cấp xã, hoặc Giám đốc/Phó Giám đốc TTPVHCC cấp xã khi có Quyết định ủy quyền còn hiệu lực (Nghị định 280/2025/NĐ-CP).", "thanh_phan_ho_so": "Bản chính hoặc bản sao có chứng thực Giấy chứng minh nhân dân hoặc Hộ chiếu còn giá trị sử dụng;\nGiấy tờ, văn bản mà mình sẽ ký.", "thoi_han_le_phi": "Thủ tục: Thủ tục Chứng thực chữ ký trong các giấy tờ, văn bản. Cơ quan có thẩm quyền giải quyết: Bộ Ngoại giao. Thời hạn giải quyết: DIRECT: Thời hạn thực hiện yêu cầu chứng thực phải được bảo đảm ngay trong ngày cơ quan, tổ chức tiếp nhận yêu cầu hoặc trong ngày làm việc tiếp theo, nếu tiếp nhận yêu cầu sau 15 giờ.. Mức phí/lệ phí: Miễn phí / Không thu lệ phí. – Miễn phí / Không thu lệ phí", "can_cu_phap_ly": "20/2015/TT-BTP\n23/2015/NĐ-CP\n264/2016/TT-BTC\n33/2009/QH12"}'),
('TTHC-CT-04', '2.001406', 'Chứng thực văn bản phân chia di sản mà di sản là động sản, quyền sử dụng đất, nhà ở', 'Chứng thực', '- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).
- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.', 'Thủ tục: Chứng thực văn bản phân chia di sản mà di sản là động sản, quyền sử dụng đất, nhà ở. Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: DIRECT: 0 ngày | ONLINE: 0 ngày | POSTAL: 0 ngày. Mức phí/lệ phí: /văn bản.', '/văn bản', 'https://dichvucong.gov.vn (API ID: 019d2bfd-9daf-70da-8f48-223498332346)', '{"trinh_tu": "+ Người yêu cầu chứng thực xuất trình một trong các giấy tờ sau: Căn cước điện tử; bản chính hoặc bản sao của Thẻ căn cước công dân hoặc Thẻ căn cước hoặc Giấy chứng nhận căn cước hoặc Hộ chiếu hoặc giấy tờ xuất nhập cảnh hoặc giấy tờ có giá trị đi lại quốc tế còn giá trị sử dụng và nộp 01 bộ hồ sơ yêu cầu chứng thực.\n\n+ Người thực hiện chứng thực (hoặc người tiếp nhận hồ sơ) kiểm tra giấy tờ trong hồ sơ yêu cầu chứng thực, nếu đầy đủ, tại thời điểm chứng thực các bên tham gia phân chia di sản tự nguyện, minh mẫn và nhận thức, làm chủ được hành vi của mình thì thực hiện chứng thực.\n\n+ Các bên tham gia phân chia di sản phải ký trước mặt người thực hiện chứng thực, nếu văn bản phân chia di sản có từ 02 (hai) trang trở lên thì phải ký vào từng trang. Trường hợp người yêu cầu chứng thực nộp hồ sơ tại Trung tâm Phục vụ hành chính công cấp xã thì các bên tham gia phân chia di sản phải ký trước mặt người tiếp nhận hồ sơ.\n\n+ Trường hợp người yêu cầu chứng thực không ký được thì phải điểm chỉ; nếu người đó không đọc được, không nghe được, không ký, không điểm chỉ được thì phải có 02 (hai) người làm chứng. Người làm chứng phải có đủ năng lực hành vi dân sự và không có quyền, lợi ích hoặc nghĩa vụ liên quan đến giao dịch. Người làm chứng do người yêu cầu chứng thực bố trí. Trường hợp người yêu cầu chứng thực không bố trí được thì đề nghị cơ quan thực hiện chứng thực chỉ định người làm chứng.\n\n+ Người thực hiện chứng thực (hoặc người tiếp nhận hồ sơ) ghi lời chứng theo mẫu quy định. Trường hợp tiếp nhận hồ sơ tại Trung tâm Phục vụ hành chính công cấp xã thì người tiếp nhận hồ sơ ký vào từng trang của văn bản phân chia di sản và ký vào dưới lời chứng theo mẫu quy định.\n\nNgười thực hiện chứng thực ký vào từng trang của văn bản phân chia di sản (nếu hồ sơ không được tiếp nhận qua Trung tâm Phục vụ hành chính công cấp xã), ký, ghi rõ họ tên, đóng dấu của cơ quan thực hiện chứng thực và ghi vào sổ chứng thực.\n\nĐối với văn bản phân chia di sản có từ 02 (hai) trang trở lên, thì từng trang phải được đánh số thứ tự, có chữ ký của người yêu cầu chứng thực và người thực hiện chứng thực; số lượng trang và lời chứng được ghi tại trang cuối của văn bản phân chia di sản. Trường hợp văn bản phân chia di sản có từ 02 (hai) tờ trở lên thì phải đóng dấu giáp lai.\n\n+ Trong trường hợp người yêu cầu chứng thực không thông thạo tiếng Việt thì phải có người phiên dịch. Người phiên dịch phải là người có năng lực hành vi dân sự đầy đủ theo quy định của pháp luật, thông thạo tiếng Việt và ngôn ngữ mà người yêu cầu chứng thực sử dụng. Người phiên dịch do người yêu cầu chứng thực mời hoặc do cơ quan thực hiện chứng thực chỉ định. Thù lao phiên dịch do người yêu cầu chứng thực trả. Người phiên dịch có trách nhiệm dịch đầy đủ, chính xác nội dung của văn bản phân chia di sản, nội dung lời chứng cho người yêu cầu chứng thực và ký vào từng trang văn bản phân chia di sản với tư cách là người phiên dịch.\n\n+ Không yêu cầu người yêu cầu chứng thực nộp, xuất trình bản chính thức hoặc bản sao các giấy tờ, tài liệu mà các thông tin trong các giấy tờ, tài liệu đã có dữ liệu trong các cơ sở dữ liệu được cơ quan chủ quản cơ sở dữ liệu công bố.\n\n+ Người thực hiện chứng thực khai thác, sử dụng thông tin đã có trong các cơ sở dữ liệu để thay thế thành phần hồ sơ giải quyết thủ tục hành chính. Trường hợp không khai thác được thông tin hoặc thông tin khai thác được không đầy đủ, không chính xác thì cơ quan, người có thẩm quyền tiếp nhận, giải quyết thủ tục hành chính yêu cầu cá nhân, tổ chức bổ sung thành phần hồ sơ để giải quyết thủ tục hành chính; đồng thời đề nghị cá nhân, tổ chức thực hiện cập nhật, điều chỉnh thông tin trong các cơ sở dữ liệu theo quy định của pháp luật.", "co_quan_thuc_hien": "- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).\n- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.", "thanh_phan_ho_so": "Dự thảo văn bản phân chia di sản\nBản chính hoặc bản sao có chứng thực hoặc bản sao điện tử được chứng thực từ bản chính của giấy chứng nhận quyền sở hữu, quyền sử dụng hoặc giấy tờ thay thế được pháp luật quy định đối với tài sản mà pháp luật quy định phải đăng ký quyền sở hữu, quyền sử dụng trong trường hợp văn bản phân chia di sản liên quan đến tài sản đó. Trường hợp nộp hồ sơ trực tiếp, người yêu cầu chứng thực có thể nộp bản sao kèm xuất trình bản chính để đối chiếu (Không yêu cầu người yêu cầu chứng thực nộp giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất khi người tiếp nhận, giải quyết thủ tục hành chính khai thác được thông tin trên Cơ sở dữ liệu quốc gia về đất đai, giai đoạn đầu áp dụng đối với đất ở).", "thoi_han_le_phi": "Thủ tục: Chứng thực văn bản phân chia di sản mà di sản là động sản, quyền sử dụng đất, nhà ở. Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: DIRECT: 0 ngày | ONLINE: 0 ngày | POSTAL: 0 ngày. Mức phí/lệ phí: /văn bản. – /văn bản", "can_cu_phap_ly": "18/2026/NĐ-CP\n66.7/2025/NQ-CP\n226/2016/TT-BTC\n280/2025/NĐ-CP\n01/2020/TT-BTP\n23/2015/NĐ-CP"}'),
('TTHC-CT-05', '2.000554', 'Thủ tục ghi vào Sổ hộ tịch việc ly hôn, hủy việc kết hôn của công dân Việt Nam đã được giải quyết tại cơ quan có thẩm quyền của nước ngoài', 'Hộ tịch', '- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).
- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.', 'Thủ tục: Thủ tục ghi vào Sổ hộ tịch việc ly hôn, hủy việc kết hôn của công dân Việt Nam đã được giải quyết tại cơ quan có thẩm quyền của nước ngoài. Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: ONLINE: 5 ngày | POSTAL: 5 ngày | DIRECT: 5 ngày. Mức phí/lệ phí: Mức lệ phí cụ thể do Hội đồng nhân dân tỉnh, thành phố trực thuộc Trung ương quyết định. Miễn lệ phí cho người thuộc gia đình có công với cách mạng; người thuộc hộ nghèo; người khuyết tật. Phí cấp bản sao Trích lục ghi chú ly hôn (nếu có yêu cầu) thực hiện theo quy định tại Thông tư số 281/2016/TT-BTC ngày 14/11/2016 của Bộ Tài chính..', 'Mức lệ phí cụ thể do Hội đồng nhân dân tỉnh, thành phố trực thuộc Trung ương quyết định. Miễn lệ phí cho người thuộc gia đình có công với cách mạng; người thuộc hộ nghèo; người khuyết tật. Phí cấp bản sao Trích lục ghi chú ly hôn (nếu có yêu cầu) thực hiện theo quy định tại Thông tư số 281/2016/TT-BTC ngày 14/11/2016 của Bộ Tài chính.', 'https://dichvucong.gov.vn (API ID: 019d2bfd-867a-70eb-bc54-e836b23a4649)', '{"trinh_tu": "- Nếu lựa chọn hình thức nộp hồ sơ trực tiếp, người yêu cầu ghi vào Sổ hộ tịch việc ly hôn, hủy việc kết hôn đã được giải quyết tại cơ quan có thẩm quyền của nước ngoài (Sau đây gọi là ghi chú ly hôn) nộp hồ sơ ghi chú ly hôn tại Trung tâm Phục vụ hành chính công có thẩm quyền; nộp lệ phí nếu thuộc trường hợp phải nộp lệ phí ghi chú ly hôn, nộp phí cấp bản sao Trích lục ghi chú ly hôn nếu có yêu cầu cấp bản sao Trích lục ghi chú ly hôn. \n- Nếu lựa chọn hình thức nộp hồ sơ trực tuyến, người yêu cầu ghi chú ly hôn truy cập Cổng dịch vụ công quốc gia hoặc Ứng dụng định danh quốc gia.\nNgười yêu cầu ghi chú ly hôn trực tuyến cung cấp thông tin theo mẫu hộ tịch điện tử tương tác ghi vào Sổ hộ tịch việc ly hôn, đính kèm bản chụp hoặc bản sao điện tử các giấy tờ, tài liệu theo quy định; nộp phí, lệ phí thông qua chức năng thanh toán trực tuyến hoặc bằng cách thức khác theo quy định pháp luật, hoàn tất việc nộp hồ sơ.\n- Cán bộ tiếp nhận hồ sơ tại Trung tâm Phục vụ hành chính công có trách nhiệm kiểm tra tính chính xác, đầy đủ, thống nhất, hợp lệ của hồ sơ. \n(i) Trường hợp hồ sơ đầy đủ, hợp lệ thì tiếp nhận hồ sơ, có Phiếu hẹn, trả kết quả cho người yêu cầu (nếu người yêu cầu nộp hồ sơ trực tiếp) hoặc gửi ngay Phiếu hẹn, trả kết quả qua thư điện tử hoặc gửi tin nhắn hẹn trả kết quả qua điện thoại di động cho người yêu cầu (nếu người yêu cầu nộp hồ sơ trực tuyến), chuyển hồ sơ để công chức tư pháp - hộ tịch xử lý; trường hợp tiếp nhận hồ sơ tại Trung tâm Phục vụ hành chính công cấp tỉnh, cán bộ tiếp nhận hồ sơ chuyển hồ sơ đến Ủy ban nhân dân cấp xã có thẩm quyền xử lý.\n(ii) Trường hợp hồ sơ chưa đầy đủ, hợp lệ thì cán bộ tiếp nhận hồ sơ thông báo cho người yêu cầu bổ sung, hoàn thiện hồ sơ, nêu rõ loại giấy tờ, nội dung cần bổ sung để người yêu cầu bổ sung, hoàn thiện. Sau khi hồ sơ được bổ sung, thực hiện lại bước (i);\n (iii) Nếu người yêu cầu ghi chú ly hôn không bổ sung, hoàn thiện được hồ sơ thì báo cáo Lãnh đạo Trung tâm Phục vụ hành chính công có văn bản từ chối giải quyết yêu cầu ghi chú ly hôn.\n- Công chức tư pháp - hộ tịch thẩm tra hồ sơ (thẩm tra tính thống nhất, hợp lệ của các thông tin trong hồ sơ, giấy tờ, tài liệu do người yêu cầu nộp, xuất trình hoặc đính kèm). \n+ Trường hợp hồ sơ cần bổ sung, hoàn thiện hoặc không đủ điều kiện giải quyết, phải từ chối thì công chức tư pháp - hộ tịch gửi thông báo về tình trạng hồ sơ tới Trung tâm Phục vụ hành chính công để thông báo cho người nộp hồ sơ – thực hiện lại bước (ii) hoặc (iii);\n+ Trường hợp cần phải kiểm tra, xác minh làm rõ hoặc do nguyên nhân khác mà không thể trả kết quả đúng thời gian đã hẹn thì công chức tư pháp - hộ tịch lập Phiếu xin lỗi và hẹn lại ngày trả kết quả, trong đó nêu rõ lý do chậm trả kết quả và thời gian hẹn trả kết quả, chuyển Trung tâm Phục vụ hành chính công để trả cho người yêu cầu (nếu người yêu cầu nộp hồ sơ trực tiếp), hoặc gửi Phiếu xin lỗi và hẹn lại ngày trả kết quả qua thư điện tử hoặc gửi tin nhắn qua điện thoại di động cho người yêu cầu (nếu người yêu cầu nộp hồ sơ trực tuyến).\n+ Nếu thấy yêu cầu ghi chú ly hôn là phù hợp quy định pháp luật, việc ly hôn, hủy việc kết hôn không thuộc trường hợp có đơn yêu cầu thi hành tại Việt Nam hoặc có đơn yêu cầu không công nhận tại Việt Nam được đăng tải trên Cổng thông tin điện tử của Bộ Tư pháp, trường hợp tiếp nhận hồ sơ ghi chú ly hôn theo hình thức trực tiếp, thì công chức tư pháp - hộ tịch thực hiện ghi vào Sổ ghi chú ly hôn, cập nhật thông tin ghi chú ly hôn trên Phần mềm đăng ký, quản lý hộ tịch điện tử dùng chung. \nTrường hợp tiếp nhận hồ sơ ghi chú ly hôn theo hình thức trực tuyến, công chức tư pháp - hộ tịch gửi lại biểu mẫu Trích lục ghi chú ly hôn điện tử với thông tin đầy đủ cho người yêu cầu qua thư điện tử hoặc thiết bị số. \nNgười yêu cầu có trách nhiệm kiểm tra tính chính xác, đầy đủ của các thông tin trên biểu mẫu Trích lục ghi chú ly hôn điện tử và xác nhận (tối đa một ngày).\nNếu người yêu cầu xác nhận thông tin đã thống nhất, đầy đủ hoặc không có phản hồi sau thời hạn một ngày thì công chức tư pháp - hộ tịch thực hiện ghi nội dung vào Sổ ghi chú ly hôn, cập nhật thông tin ghi chú ly hôn trên Phần mềm đăng ký, quản lý hộ tịch điện tử dùng chung. \n- Công chức tư pháp - hộ tịch in Trích lục ghi chú ly hôn, trình Lãnh đạo Ủy ban nhân dân cấp xã ký, chuyển Trung tâm Phục vụ hành chính công để trả kết quả cho người yêu cầu.", "co_quan_thuc_hien": "- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).\n- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.", "thanh_phan_ho_so": "- Giấy tờ chứng minh nơi cư trú để xác định thẩm quyền (trong trường hợp công dân Việt Nam từ nước ngoài về thường trú tại Việt Nam có yêu cầu ghi chú ly hôn, công dân Việt Nam không thường trú tại Việt Nam yêu cầu ghi chú ly hôn tại Ủy ban nhân dân cấp huyện nơi cư trú trước khi xuất cảnh) trong trường hợp cơ quan đăng ký hộ tịch không thể khai thác được thông tin về nơi cư trú của công dân theo các phương thức quy định tại khoản 2 Điều 14 Nghị định số 104/2022/NĐ-CP ngày 21/12/2022 của Chính phủ. Trường hợp các thông tin về giấy tờ chứng minh nơi cư trú đã được khai thác từ Cơ sở dữ liệu quốc gia về dân cư bằng các phương thức này thì người có yêu cầu không phải xuất trình (theo hình thức trực tiếp) hoặc tải lên (theo hình thức trực tuyến).\n- Trường hợp gửi hồ sơ qua hệ thống bưu chính thì phải gửi kèm theo bản sao có chứng thực các giấy tờ phải xuất trình nêu trên.\nTrường hợp các thông tin cá nhân trong các giấy tờ này đã có trong Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu hộ tịch điện tử, được hệ thống điền tự động thì không phải tải lên (theo hình thức trực tuyến)\nTrường hợp không khai thác được thông tin hoặc thông tin khai thác được không đầy đủ, không chính xác thì cơ quan đăng ký hộ tịch yêu cầu người đi đăng ký hộ tịch xuất trình bản chính giấy tờ để chứng minh, đồng thời đề nghị người đi đăng ký hộ tịch cập nhật, điều chỉnh thông tin trong các cơ sở dữ liệu theo quy định của pháp luật.\nTrường hợp giấy tờ tùy thân sử dụng là: Hộ chiếu, Thẻ căn cước, Căn cước công dân, Giấy chứng nhận căn cước thì người có yêu cầu đăng ký hộ tịch chỉ cần cung cấp thông tin số định danh cá nhân hoặc thông tin về giấy tờ (số, ngày/tháng/năm cấp), cơ quan đăng ký hộ tịch có trách nhiệm tra cứu thông tin thông qua kết nối với Cơ sở dữ liệu hộ tịch điện tử, Cơ sở dữ liệu quốc gia về dân cư hoặc cơ sở dữ liệu khác có liên quan để đối chiếu, khai thác dữ liệu.\n- Hộ chiếu/Thẻ căn cước công dân/Thẻ căn cước/Căn cước điện tử/Giấy chứng nhận căn cước hoặc các giấy tờ khác có dán ảnh và thông tin cá nhân do cơ quan có thẩm quyền cấp, còn giá trị sử dụng (sau đây gọi tắt là giấy tờ tùy thân) để chứng minh về nhân thân khi làm thủ tục trực tiếp tại cơ quan đăng ký hộ tịch.\n- Văn bản ủy quyền (được chứng thực) theo quy định của pháp luật trong trường hợp ủy quyền thực hiện việc ghi chú ly hôn. Trường hợp người được ủy quyền là ông, bà, cha, mẹ, con, vợ, chồng, anh, chị, em ruột của người ủy quyền thì văn bản ủy quyền không phải chứng thực.\n- Bản sao Bản án, quyết định ly hôn, hủy kết hôn, văn bản thỏa thuận ly hôn hoặc giấy tờ khác công nhận việc ly hôn do cơ quan có thẩm quyền của nước ngoài cấp đã có hiệu lực pháp luật;\n- Cá nhân có quyền lựa chọn thực hiện thủ tục hành chính về hộ tịch tại cơ quan đăng ký hộ tịch nơi cư trú; nơi cư trú của cá nhân được xác định theo quy định của pháp luật về cư trú. Trường hợp cá nhân lựa chọn thực hiện thủ tục hành chính về hộ tịch không phải tại Ủy ban nhân dân cấp xã nơi thường trú hoặc nơi tạm trú thì Ủy ban nhân dân cấp xã nơi tiếp nhận yêu cầu có trách nhiệm hỗ trợ người dân nộp hồ sơ đăng ký hộ tịch trực tuyến đến đúng cơ quan có thẩm quyền theo quy định.\n- Trường hợp người yêu cầu đăng k‎ý hộ tịch lựa chọn nhận kết quả tại Trung tâm Phục vụ hành chính công thì người yêu cầu đăng ký hộ tịch phải xuất trình giấy tờ tuỳ thân, nộp các giấy tờ là thành phần hồ sơ theo quy định; Trường hợp người yêu cầu đăng ký hộ tịch không lựa chọn nhận kết quả tại Trung tâm Phục vụ hành chính công thì người yêu cầu đăng ký hộ tịch nộp các giấy tờ là thành phần hồ sơ theo quy định trước khi nhận kết quả.\n+ Người yêu cầu đăng ký hộ tịch có thể nộp bản sao được chứng thực từ bản chính hoặc bản sao được cấp từ sổ gốc (sau đây gọi là bản sao) hoặc bản chụp kèm theo bản chính, bản điện tử các giấy tờ này, bao gồm cả giấy tờ được tích hợp, hiển thị trên Ứng dụng định danh điện tử (VneID).\n- Trường hợp người yêu cầu đăng ký hộ tịch không cung cấp được giấy tờ theo quy định hoặc giấy tờ nộp, xuất trình bị tẩy xóa, sửa chữa, làm giả thì cơ quan đăng ký hộ tịch có thẩm quyền hủy bỏ kết quả đăng ký hộ tịch.\n+ Người tiếp nhận hồ sơ thực hiện khai thác thông tin trong CSDLQGVDC theo quy định pháp luật nếu người yêu cầu đăng ký hộ tịch đã cung cấp họ, chữ đệm, tên; ngày, tháng, năm sinh; số định danh cá nhân/thẻ căn cước công dân/thẻ căn cước/căn cước điện tử. Trường hợp các thông tin cần khai thác không có trong CSDLQGVDC thì đề nghị người yêu cầu kê khai đầy đủ.\n- Giấy tờ do cơ quan có thẩm quyền của nước ngoài cấp, công chứng hoặc xác nhận để sử dụng cho việc đăng ký hộ tịch tại Việt Nam phải được hợp pháp hóa lãnh sự theo quy định của pháp luật, trừ trường hợp được miễn theo điều ước quốc tế mà Việt Nam là thành viên.\nTrường hợp người yêu cầu nộp bản chụp kèm theo bản chính giấy tờ thì người tiếp nhận có trách nhiệm kiểm tra, đối chiếu bản chụp với bản chính và ký xác nhận, không được yêu cầu nộp bản sao giấy tờ đó.\n- Đối với giấy tờ nộp, xuất trình nếu người yêu cầu nộp hồ sơ theo hình thức trực tiếp:\n- Đối với giấy tờ gửi kèm theo nếu người yêu cầu nộp hồ sơ theo hình thức trực tuyến:\n+ Bản chụp các giấy tờ gửi kèm theo hồ sơ ghi chú ly hôn trực tuyến phải bảo đảm rõ nét, đầy đủ, toàn vẹn về nội dung, là bản chụp bằng máy ảnh, điện thoại hoặc được chụp, được quét bằng thiết bị điện tử, từ giấy tờ được cấp hợp lệ, còn giá trị sử dụng.\n+ Người tiếp nhận có trách nhiệm tiếp nhận đúng, đủ hồ sơ đăng ký hộ tịch theo quy định của pháp luật hộ tịch, không được yêu cầu người đăng ký hộ tịch nộp thêm giấy tờ mà pháp luật hộ tịch không quy định phải nộp .\n+ Đối với giấy tờ xuất trình khi đăng ký hộ tịch, người tiếp nhận có trách nhiệm kiểm tra, đối chiếu với thông tin trong tờ khai, chụp lại hoặc ghi lại thông tin để lưu trong hồ sơ và trả lại cho người xuất trình, không được yêu cầu nộp bản sao hoặc bản chụp giấy tờ đó.\n+ Trường hợp giấy tờ, tài liệu phải gửi kèm trong hồ sơ ghi chú ly hôn trực tuyến đã có bản sao điện tử hoặc đã có bản điện tử giấy tờ hộ tịch thì người yêu cầu được sử dụng bản điện tử này.\n- Người có yêu cầu ghi chú ly hôn thực hiện việc nộp/xuất trình (theo hình thức trực tiếp) hoặc tải lên (theo hình thức trực tuyến) các giấy tờ sau:\n- Mẫu hộ tịch điện tử tương tác ghi vào Sổ hộ tịch việc ly hôn (do người yêu cầu cung cấp thông tin theo hướng dẫn trên Cổng dịch vụ công, nếu người có yêu cầu lựa chọn nộp hồ sơ theo hình thức trực tuyến)\n- Tờ khai ghi chú ly hôn theo mẫu (nếu người có yêu cầu lựa chọn nộp hồ sơ theo hình thức trực tiếp hoặc gửi hồ sơ qua hệ thống bưu chính);", "thoi_han_le_phi": "Thủ tục: Thủ tục ghi vào Sổ hộ tịch việc ly hôn, hủy việc kết hôn của công dân Việt Nam đã được giải quyết tại cơ quan có thẩm quyền của nước ngoài. Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: ONLINE: 5 ngày | POSTAL: 5 ngày | DIRECT: 5 ngày. Mức phí/lệ phí: Mức lệ phí cụ thể do Hội đồng nhân dân tỉnh, thành phố trực thuộc Trung ương quyết định. Miễn lệ phí cho người thuộc gia đình có công với cách mạng; người thuộc hộ nghèo; người khuyết tật. Phí cấp bản sao Trích lục ghi chú ly hôn (nếu có yêu cầu) thực hiện theo quy định tại Thông tư số 281/2016/TT-BTC ngày 14/11/2016 của Bộ Tài chính.. – Mức lệ phí cụ thể do Hội đồng nhân dân tỉnh, thành phố trực thuộc Trung ương quyết định. Miễn lệ phí cho người thuộc gia đình có công với cách mạng; người thuộc hộ nghèo; người khuyết tật. Phí cấp bản sao Trích lục ghi chú ly hôn (nếu có yêu cầu) thực hiện theo quy định tại Thông tư số 281/2016/TT-BTC ngày 14/11/2016 của Bộ Tài chính.", "can_cu_phap_ly": "04/2024/TT-BTP\nThông tư số 03/2023/TT-BTP\n106/2021/TT-BTC\n85/2019/TT-BTC\n104/2022/NĐ-CP\n123/2015/NĐ-CP\n08/2025/TT-BTP\n18/2026/NĐ-CP\n87/2020/NĐ-CP\n04/2020/TT-BTP\n07/2025/NĐ-CP\n120/2025/NĐ-CP\n66.7/2025/NQ-CP\n60/2014/QH13\n01/2022/TT-BTP\nThông tư số 281/2016/TT-BTC"}'),
('TTHC-CT-06', '2.000547', 'Thủ tục ghi vào Sổ hộ tịch việc hộ tịch khác của công dân Việt Nam đã được giải quyết tại cơ quan có thẩm quyền của nước ngoài (khai sinh; giám hộ; nhận cha, mẹ, con; xác định cha, mẹ, con; nuôi con nuôi; khai tử; thay đổi hộ tịch)', 'Hộ tịch', '- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).
- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.', 'Thủ tục: Thủ tục ghi vào Sổ hộ tịch việc hộ tịch khác của công dân Việt Nam đã được giải quyết tại cơ quan có thẩm quyền của nước ngoài (khai sinh; giám hộ; nhận cha, mẹ, con; xác định cha, mẹ, con; nuôi con nuôi; khai tử; thay đổi hộ tịch). Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: ONLINE: 1 ngày | POSTAL: 1 ngày | DIRECT: 1 ngày. Mức phí/lệ phí: Theo mức thu lệ phí do Hội đồng nhân dân cấp tỉnh quy định. Miễn lệ phí cho người thuộc gia đình có công với cách mạng; người thuộc hộ nghèo; người khuyết tật. Phí cấp bản sao Trích lục ghi vào Sổ hộ tịch việc khai sinh/Trích lục ghi vào Sổ hộ tịch các việc hộ tịch khác (nếu có yêu cầu) thực hiện theo quy định tại Thông tư số 281/2016/TT-BTC ngày 14/11/2016 của Bộ Tài chính..', 'Theo mức thu lệ phí do Hội đồng nhân dân cấp tỉnh quy định. Miễn lệ phí cho người thuộc gia đình có công với cách mạng; người thuộc hộ nghèo; người khuyết tật. Phí cấp bản sao Trích lục ghi vào Sổ hộ tịch việc khai sinh/Trích lục ghi vào Sổ hộ tịch các việc hộ tịch khác (nếu có yêu cầu) thực hiện theo quy định tại Thông tư số 281/2016/TT-BTC ngày 14/11/2016 của Bộ Tài chính.', 'https://dichvucong.gov.vn (API ID: 019d2bfd-8661-77ca-9811-6106ea8c43db)', '{"trinh_tu": "- Nếu lựa chọn hình thức nộp hồ sơ trực tiếp, người yêu cầu ghi vào Sổ hộ tịch việc khai sinh; giám hộ; nhận cha, mẹ, con; xác định cha, mẹ, con; nuôi con nuôi; khai tử; thay đổi hộ tịch đã được giải quyết tại cơ quan có thẩm quyền của nước ngoài (Sau đây gọi là ghi vào Sổ hộ tịch các việc hộ tịch khác) nộp hồ sơ ghi vào Sổ hộ tịch các việc hộ tịch khác tại Trung tâm Phục vụ hành chính công có thẩm quyền; nộp lệ phí nếu thuộc trường hợp phải nộp lệ phí ghi vào Sổ hộ tịch các việc hộ tịch khác; nộp phí cấp bản sao Trích lục hộ tịch, bản sao Giấy khai sinh tương ứng nếu có yêu cầu. \n- Nếu lựa chọn hình thức nộp hồ sơ trực tuyến, người yêu cầu ghi vào Sổ hộ tịch các việc hộ tịch khác truy cập Cổng dịch vụ công quốc gia hoặc Ứng dụng định danh quốc gia.\nNgười yêu cầu ghi vào Sổ hộ tịch các việc hộ tịch khác trực tuyến cung cấp thông tin theo mẫu hộ tịch điện tử tương tác ghi vào Sổ hộ tịch việc khai sinh/khai tử/nuôi con nuôi/giám hộ, nhận cha, mẹ,con/mẫu hộ tịch điện tử tương tác ghi vào Sổ hộ tịch các việc hộ tịch khác , đính kèm bản chụp hoặc bản sao điện tử các giấy tờ, tài liệu theo quy định; nộp phí, lệ phí thông qua chức năng thanh toán trực tuyến hoặc bằng cách thức khác theo quy định pháp luật, hoàn tất việc nộp hồ sơ. \n- Cán bộ tiếp nhận hồ sơ tại Trung tâm Phục vụ hành chính công có trách nhiệm kiểm tra tính chính xác, đầy đủ, thống nhất, hợp lệ của hồ sơ. \n(i) Trường hợp hồ sơ đầy đủ, hợp lệ thì tiếp nhận hồ sơ; nếu tiếp nhận hồ sơ sau 15 giờ thì có Phiếu hẹn, trả kết quả cho người yêu cầu trong ngày làm việc tiếp theo (nếu người yêu cầu nộp hồ sơ trực tiếp) hoặc gửi ngay Phiếu hẹn, trả kết quả qua thư điện tử hoặc gửi tin nhắn hẹn trả kết quả qua điện thoại di động cho người yêu cầu (nếu người yêu cầu nộp hồ sơ trực tuyến); chuyển hồ sơ để công chức tư pháp - hộ tịch xử lý; trường hợp tiếp nhận hồ sơ tại Trung tâm Phục vụ hành chính công cấp tỉnh, cán bộ tiếp nhận hồ sơ chuyển hồ sơ đến Ủy ban nhân dân cấp xã có thẩm quyền xử lý.\n(ii) Trường hợp hồ sơ chưa đầy đủ, hợp lệ thì cán bộ tiếp nhận hồ sơ thông báo cho người yêu cầu bổ sung, hoàn thiện hồ sơ, nêu rõ loại giấy tờ, nội dung cần bổ sung để người yêu cầu bổ sung, hoàn thiện. Sau khi hồ sơ được bổ sung, thực hiện lại bước (i);\n(iii) Trường hợp người yêu cầu ghi vào Sổ hộ tịch các việc hộ tịch khác không bổ sung, hoàn thiện được hồ sơ thì cán bộ tiếp nhận hồ sơ báo cáo Lãnh đạo Trung tâm Phục vụ hành chính công có thông báo từ chối giải quyết yêu cầu ghi vào Sổ hộ tịch các việc hộ tịch khác.\n- Công chức tư pháp - hộ tịch thẩm tra hồ sơ (thẩm tra tính thống nhất, hợp lệ của các thông tin trong hồ sơ, giấy tờ, tài liệu do người yêu cầu nộp, xuất trình hoặc đính kèm). \n+ Trường hợp hồ sơ cần bổ sung, hoàn thiện hoặc không đủ điều kiện giải quyết, phải từ chối thì công chức tư pháp - hộ tịch gửi thông báo về tình trạng hồ sơ tới Trung tâm Phục vụ hành chính công để thông báo cho người nộp hồ sơ – thực hiện lại bước (ii) hoặc (iii);\n+ Trường hợp cần phải kiểm tra, xác minh làm rõ hoặc do nguyên nhân khác mà không thể trả kết quả đúng thời gian đã hẹn thì công chức tư pháp - hộ tịch lập Phiếu xin lỗi và hẹn lại ngày trả kết quả, trong đó nêu rõ lý do chậm trả kết quả và thời gian hẹn trả kết quả, chuyển Trung tâm Phục vụ hành chính công để trả cho người yêu cầu (nếu người yêu cầu nộp hồ sơ trực tiếp), hoặc gửi Phiếu xin lỗi và hẹn lại ngày trả kết quả qua thư điện tử hoặc gửi tin nhắn qua điện thoại di động cho người yêu cầu (nếu người yêu cầu nộp hồ sơ trực tuyến).\n+ Nếu thấy yêu cầu ghi vào Sổ hộ tịch việc hộ tịch khác đủ điều kiện, phù hợp quy định pháp luật, trường hợp tiếp nhận hồ sơ ghi vào Sổ hộ tịch các việc hộ tịch khác theo hình thức trực tiếp, thì công chức tư pháp - hộ tịch thực hiện ghi nội dung ghi chú vào Sổ hộ tịch, cập nhật thông tin ghi vào Sổ hộ tịch các việc hộ tịch khác trên Phần mềm đăng ký, quản lý hộ tịch điện tử dùng chung. \nTrường hợp tiếp nhận hồ sơ ghi vào Sổ hộ tịch các việc hộ tịch khác theo hình thức trực tuyến, công chức tư pháp - hộ tịch gửi lại biểu mẫu Trích lục ghi vào Sổ hộ tịch việc khai sinh/Trích lục ghi vào Sổ hộ tịch các việc hộ tịch khác điện tử cho người yêu cầu qua thư điện tử hoặc thiết bị số. \nNgười yêu cầu có trách nhiệm kiểm tra tính chính xác, đầy đủ của các thông tin trên biểu mẫu Trích lục ghi vào sổ hộ tịch việc khai sinh/Trích lục ghi vào sổ hộ tịch các việc hộ tịch khác điện tử và xác nhận (tối đa một ngày). \nNếu người yêu cầu xác nhận thông tin đã thống nhất, đầy đủ hoặc không có phản hồi sau thời hạn một ngày thì công chức tư pháp - hộ tịch thực hiện ghi nội dung ghi chú vào Sổ hộ tịch, cập nhật thông tin ghi vào Sổ hộ tịch các việc hộ tịch khác trên Phần mềm đăng ký, quản lý hộ tịch điện tử dùng chung. \n- Công chức tư pháp - hộ tịch in Trích lục ghi vào Sổ hộ tịch việc khai sinh/Trích lục ghi vào Sổ hộ tịch các việc hộ tịch khác, trình Lãnh đạo Ủy ban nhân dân cấp xã ký, chuyển tới Trung tâm Phục vụ hành chính công để trả kết quả cho người yêu cầu.", "co_quan_thuc_hien": "- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).\n- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.", "thanh_phan_ho_so": "Trường hợp không khai thác được thông tin hoặc thông tin khai thác được không đầy đủ, không chính xác thì cơ quan đăng ký hộ tịch yêu cầu người đi đăng ký hộ tịch xuất trình bản chính giấy tờ để chứng minh, đồng thời đề nghị người đi đăng ký hộ tịch cập nhật, điều chỉnh thông tin trong các cơ sở dữ liệu theo quy định của pháp luật.\n- Trường hợp gửi hồ sơ qua hệ thống bưu chính thì phải gửi kèm theo bản sao có chứng thực các giấy tờ phải xuất trình nêu trên.\nTrường hợp các thông tin cá nhân trong các giấy tờ này đã có trong Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu hộ tịch điện tử, được hệ thống điền tự động thì không phải tải lên (theo hình thức trực tuyến)\nTrường hợp giấy tờ tùy thân sử dụng là: Hộ chiếu, Thẻ căn cước, Căn cước công dân, Giấy chứng nhận căn cước thì người có yêu cầu đăng ký hộ tịch chỉ cần cung cấp thông tin số định danh cá nhân hoặc thông tin về giấy tờ (số, ngày/tháng/năm cấp), cơ quan đăng ký hộ tịch có trách nhiệm tra cứu thông tin thông qua kết nối với Cơ sở dữ liệu hộ tịch điện tử, Cơ sở dữ liệu quốc gia về dân cư hoặc cơ sở dữ liệu khác có liên quan để đối chiếu, khai thác dữ liệu.\n- Hộ chiếu/Thẻ căn cước công dân/Thẻ căn cước/Căn cước điện tử/Giấy chứng nhận căn cước hoặc các giấy tờ khác có dán ảnh và thông tin cá nhân do cơ quan có thẩm quyền cấp, còn giá trị sử dụng (sau đây gọi tắt là giấy tờ tùy thân) để chứng minh về nhân thân khi làm thủ tục trực tiếp tại cơ quan đăng ký hộ tịch.\n- Giấy tờ có giá trị chứng minh thông tin về cư trú trong trường hợp cơ quan đăng ký hộ tịch không thể khai thác được thông tin về nơi cư trú của công dân theo các phương thức quy định tại khoản 2 Điều 14 Nghị định số 104/2022/NĐ-CP ngày 21/12/2022 của Chính phủ. Trường hợp các thông tin về giấy tờ chứng minh nơi cư trú đã được khai thác từ Cơ sở dữ liệu quốc gia về dân cư bằng các phương thức này thì người có yêu cầu không phải xuất trình (theo hình thức trực tiếp) hoặc tải lên (theo hình thức trực tuyến).\n- Bản sao giấy tờ chứng minh việc hộ tịch đã được giải quyết tại cơ quan có thẩm quyền của nước ngoài.\n- Văn bản ủy quyền (được chứng thực) theo quy định của pháp luật trong trường hợp ủy quyền thực hiện việc ghi chú. Trường hợp người được ủy quyền là ông, bà, cha, mẹ, con, vợ, chồng, anh, chị, em ruột của người ủy quyền thì văn bản ủy quyền không phải chứng thực.\n- Giấy tờ do cơ quan có thẩm quyền của nước ngoài cấp, công chứng hoặc xác nhận để sử dụng cho việc đăng ký hộ tịch tại Việt Nam phải được hợp pháp hóa lãnh sự theo quy định của pháp luật, trừ trường hợp được miễn theo điều ước quốc tế mà Việt Nam là thành viên.\n+ Bản chụp các giấy tờ gửi kèm theo hồ sơ cầu ghi vào Sổ hộ tịch các việc hộ tịch khác trực tuyến phải bảo đảm rõ nét, đầy đủ, toàn vẹn về nội dung, là bản chụp bằng máy ảnh, điện thoại hoặc được chụp, được quét bằng thiết bị điện tử, từ giấy tờ được cấp hợp lệ, còn giá trị sử dụng.\n- Trường hợp người yêu cầu đăng k‎ý hộ tịch lựa chọn nhận kết quả tại Trung tâm Phục vụ hành chính công thì người yêu cầu đăng ký hộ tịch phải xuất trình giấy tờ tuỳ thân, nộp các giấy tờ là thành phần hồ sơ theo quy định; Trường hợp người yêu cầu đăng ký hộ tịch không lựa chọn nhận kết quả tại Trung tâm Phục vụ hành chính công thì người yêu cầu đăng ký hộ tịch nộp các giấy tờ là thành phần hồ sơ theo quy định trước khi nhận kết quả.\n+ Người yêu cầu đăng ký hộ tịch có thể nộp bản sao được chứng thực từ bản chính hoặc bản sao được cấp từ sổ gốc (sau đây gọi là bản sao) hoặc bản chụp kèm theo bản chính, bản điện tử các giấy tờ này, bao gồm cả giấy tờ được tích hợp, hiển thị trên Ứng dụng định danh điện tử (VneID).\nTrường hợp người yêu cầu nộp bản chụp kèm theo bản chính giấy tờ thì người tiếp nhận có trách nhiệm kiểm tra, đối chiếu bản chụp với bản chính và ký xác nhận, không được yêu cầu nộp bản sao giấy tờ đó.\n+ Trường hợp giấy tờ, tài liệu phải gửi kèm trong hồ sơ ghi vào Sổ hộ tịch các việc hộ tịch khác trực tuyến đã có bản sao điện tử hoặc đã có bản điện tử giấy tờ hộ tịch thì người yêu cầu được sử dụng bản điện tử này.\n- Cá nhân có quyền lựa chọn thực hiện thủ tục hành chính về hộ tịch tại cơ quan đăng ký hộ tịch nơi cư trú; nơi cư trú của cá nhân được xác định theo quy định của pháp luật về cư trú. Trường hợp cá nhân lựa chọn thực hiện thủ tục hành chính về hộ tịch không phải tại Ủy ban nhân dân cấp xã nơi thường trú hoặc nơi tạm trú thì Ủy ban nhân dân cấp xã nơi tiếp nhận yêu cầu có trách nhiệm hỗ trợ người dân nộp hồ sơ đăng ký hộ tịch trực tuyến đến đúng cơ quan có thẩm quyền theo quy định.\n+ Người tiếp nhận có trách nhiệm tiếp nhận đúng, đủ hồ sơ đăng ký hộ tịch theo quy định của pháp luật hộ tịch, không được yêu cầu người đăng ký hộ tịch nộp thêm giấy tờ mà pháp luật hộ tịch không quy định phải nộp .\n- Đối với giấy tờ nộp, xuất trình nếu người yêu cầu nộp hồ sơ theo hình thức trực tiếp:\n+ Người tiếp nhận hồ sơ thực hiện khai thác thông tin trong CSDLQGVDC theo quy định pháp luật nếu người yêu cầu đăng ký hộ tịch đã cung cấp họ, chữ đệm, tên; ngày, tháng, năm sinh; số định danh cá nhân/thẻ căn cước công dân/thẻ căn cước/căn cước điện tử. Trường hợp các thông tin cần khai thác không có trong CSDLQGVDC thì đề nghị người yêu cầu kê khai đầy đủ.\n- Trường hợp người yêu cầu đăng ký hộ tịch không cung cấp được giấy tờ theo quy định hoặc giấy tờ nộp, xuất trình bị tẩy xóa, sửa chữa, làm giả thì cơ quan đăng ký hộ tịch có thẩm quyền hủy bỏ kết quả đăng ký hộ tịch.\n+ Đối với giấy tờ xuất trình khi đăng ký hộ tịch, người tiếp nhận có trách nhiệm kiểm tra, đối chiếu với thông tin trong tờ khai, chụp lại hoặc ghi lại thông tin để lưu trong hồ sơ và trả lại cho người xuất trình, không được yêu cầu nộp bản sao hoặc bản chụp giấy tờ đó.\n- Đối với giấy tờ gửi kèm theo nếu người yêu cầu nộp hồ sơ theo hình thức trực tuyến:\n- Mẫu hộ tịch điện tử tương tác ghi vào Sổ hộ tịch việc giám hộ,nhận cha, mẹ,con (do người yêu cầu cung cấp thông tin theo hướng dẫn trên Cổng dịch vụ công, nếu người có yêu cầu lựa chọn nộp hồ sơ theo hình thức trực tuyến)\n- Mẫu hộ tịch điện tử tương tác ghi vào Sổ hộ tịch các việc hộ tịch khác (do người yêu cầu cung cấp thông tin theo hướng dẫn trên Cổng dịch vụ công, nếu người có yêu cầu lựa chọn nộp hồ sơ theo hình thức trực tuyến)\n- Mẫu hộ tịch điện tử tương tác ghi vào Sổ hộ tịch việc khai tử (do người yêu cầu cung cấp thông tin theo hướng dẫn trên Cổng dịch vụ công, nếu người có yêu cầu lựa chọn nộp hồ sơ theo hình thức trực tuyến)\n- Người có yêu cầu ghi vào Sổ hộ tịch các việc hộ tịch khác thực hiện việc nộp/xuất trình (theo hình thức trực tiếp) hoặc tải lên (theo hình thức trực tuyến) các giấy tờ sau:\n- Tờ khai ghi vào Sổ hộ tịch việc khai sinh/Tờ khai ghi vào Sổ hộ tịch việc khai tử/Tờ khai ghi vào Sổ hộ tịch việc nuôi con nuôi/ Tờ khai ghi vào Sổ hộ tịch việc giám hộ, nhận cha, mẹ, con/Tờ khai ghi vào Sổ hộ tịch các việc hộ tịch khác theo mẫu (nếu người có yêu cầu lựa chọn nộp hồ sơ theo hình thức trực tiếp);\n- Mẫu hộ tịch điện tử tương tác ghi vào Sổ hộ tịch việc khai sinh (do người yêu cầu cung cấp thông tin theo hướng dẫn trên Cổng dịch vụ công, nếu người có yêu cầu lựa chọn nộp hồ sơ theo hình thức trực tuyến)\n- Mẫu hộ tịch điện tử tương tác ghi vào Sổ hộ tịch việc nuôi con nuôi (do người yêu cầu cung cấp thông tin theo hướng dẫn trên Cổng dịch vụ công, nếu người có yêu cầu lựa chọn nộp hồ sơ theo hình thức trực tuyến)", "thoi_han_le_phi": "Thủ tục: Thủ tục ghi vào Sổ hộ tịch việc hộ tịch khác của công dân Việt Nam đã được giải quyết tại cơ quan có thẩm quyền của nước ngoài (khai sinh; giám hộ; nhận cha, mẹ, con; xác định cha, mẹ, con; nuôi con nuôi; khai tử; thay đổi hộ tịch). Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: ONLINE: 1 ngày | POSTAL: 1 ngày | DIRECT: 1 ngày. Mức phí/lệ phí: Theo mức thu lệ phí do Hội đồng nhân dân cấp tỉnh quy định. Miễn lệ phí cho người thuộc gia đình có công với cách mạng; người thuộc hộ nghèo; người khuyết tật. Phí cấp bản sao Trích lục ghi vào Sổ hộ tịch việc khai sinh/Trích lục ghi vào Sổ hộ tịch các việc hộ tịch khác (nếu có yêu cầu) thực hiện theo quy định tại Thông tư số 281/2016/TT-BTC ngày 14/11/2016 của Bộ Tài chính.. – Theo mức thu lệ phí do Hội đồng nhân dân cấp tỉnh quy định. Miễn lệ phí cho người thuộc gia đình có công với cách mạng; người thuộc hộ nghèo; người khuyết tật. Phí cấp bản sao Trích lục ghi vào Sổ hộ tịch việc khai sinh/Trích lục ghi vào Sổ hộ tịch các việc hộ tịch khác (nếu có yêu cầu) thực hiện theo quy định tại Thông tư số 281/2016/TT-BTC ngày 14/11/2016 của Bộ Tài chính.", "can_cu_phap_ly": "04/2020/TT-BTP\n07/2025/NĐ-CP\n120/2025/NĐ-CP\n85/2019/TT-BTC\n104/2022/NĐ-CP\n123/2015/NĐ-CP\n08/2025/TT-BTP\n18/2026/NĐ-CP\n87/2020/NĐ-CP\n04/2024/TT-BTP\n106/2021/TT-BTC\n66.7/2025/NQ-CP\n60/2014/QH13\n01/2022/TT-BTP\n03/2023/TT-BTP\n281/2016/TT-BTC"}'),
('TTHC-CT-07', '2.001016', 'Chứng thực văn bản từ chối nhận di sản', 'Chứng thực', '- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).
- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.', 'Thủ tục: Chứng thực văn bản từ chối nhận di sản. Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: DIRECT: 0 ngày | ONLINE: 0 ngày | POSTAL: 0 ngày. Mức phí/lệ phí: /văn bản.', '/văn bản', 'https://dichvucong.gov.vn (API ID: 019d2bfd-95e6-7578-ba2d-d1b4373cd174)', '{"trinh_tu": "+ Người yêu cầu chứng thực xuất trình một trong các giấy tờ sau: Căn cước điện tử; bản chính hoặc bản sao của Thẻ căn cước công dân hoặc Thẻ căn cước hoặc Giấy chứng nhận căn cước hoặc Hộ chiếu hoặc giấy tờ xuất nhập cảnh hoặc giấy tờ có giá trị đi lại quốc tế còn giá trị sử dụng và nộp 01 bộ hồ sơ yêu cầu chứng thực.\n\n+ Người thực hiện chứng thực (hoặc người tiếp nhận hồ sơ) kiểm tra giấy tờ trong hồ sơ yêu cầu chứng thực, nếu đầy đủ, tại thời điểm chứng thực người từ chối nhận di sản tự nguyện, minh mẫn và nhận thức, làm chủ được hành vi của mình thì thực hiện chứng thực.\n\n+ Người từ chối nhận di sản ký trước mặt người thực hiện chứng thực, nếu văn bản từ chối nhận di sản có từ 02 (hai) trang trở lên thì phải ký vào từng trang. Trường hợp người yêu cầu chứng thực nộp hồ sơ tại Trung tâm Phục vụ hành chính công cấp xã thì phải ký trước mặt người tiếp nhận hồ sơ.\n\n+ Trường hợp người yêu cầu chứng thực không ký được thì phải điểm chỉ; nếu người đó không đọc được, không nghe được, không ký, không điểm chỉ được thì phải có 02 (hai) người làm chứng. Người làm chứng phải có đủ năng lực hành vi dân sự và không có quyền, lợi ích hoặc nghĩa vụ liên quan đến giao dịch. Người làm chứng do người yêu cầu chứng thực bố trí. Trường hợp người yêu cầu chứng thực không bố trí được thì đề nghị cơ quan thực hiện chứng thực chỉ định người làm chứng.\n\n+ Người thực hiện chứng thực (hoặc người tiếp nhận hồ sơ) ghi lời chứng theo mẫu quy định. Trường hợp tiếp nhận hồ sơ tại Trung tâm Phục vụ hành chính công cấp xã thì người tiếp nhận hồ sơ ký vào từng trang của văn bản từ chối nhận di sản và ký vào dưới lời chứng theo mẫu quy định.\n\nNgười thực hiện chứng thực ký vào từng trang của văn bản từ chối nhận di sản (nếu hồ sơ không được tiếp nhận qua Trung tâm Phục vụ hành chính công cấp xã), ký, ghi rõ họ tên, đóng dấu của cơ quan thực hiện chứng thực và ghi vào sổ chứng thực.\n\nĐối với văn bản từ chối nhận di sản có từ 02 (hai) trang trở lên, thì từng trang phải được đánh số thứ tự, có chữ ký của người yêu cầu chứng thực và người thực hiện chứng thực; số lượng trang và lời chứng được ghi tại trang cuối của văn bản từ chối nhận di sản. Trường hợp văn bản từ chối nhận di sản có từ 02 (hai) tờ trở lên thì phải đóng dấu giáp lai.\n\n+ Trong trường hợp người yêu cầu chứng thực không thông thạo tiếng Việt thì phải có người phiên dịch. Người phiên dịch phải là người có năng lực hành vi dân sự đầy đủ theo quy định của pháp luật, thông thạo tiếng Việt và ngôn ngữ mà người yêu cầu chứng thực sử dụng. Người phiên dịch do người yêu cầu chứng thực mời hoặc do cơ quan thực hiện chứng thực chỉ định. Thù lao phiên dịch do người yêu cầu chứng thực trả. Người phiên dịch có trách nhiệm dịch đầy đủ, chính xác nội dung của văn bản từ chối nhận di sản, nội dung lời chứng cho người yêu cầu chứng thực và ký vào từng trang văn bản từ chối nhận di sản với tư cách là người phiên dịch.\n\n+ Không yêu cầu người yêu cầu chứng thực nộp, xuất trình bản chính thức hoặc bản sao các giấy tờ, tài liệu mà các thông tin trong các giấy tờ, tài liệu đã có dữ liệu trong các cơ sở dữ liệu được cơ quan chủ quản cơ sở dữ liệu công bố.\n\n+ Người thực hiện chứng thực khai thác, sử dụng thông tin đã có trong các cơ sở dữ liệu để thay thế thành phần hồ sơ giải quyết thủ tục hành chính. Trường hợp không khai thác được thông tin hoặc thông tin khai thác được không đầy đủ, không chính xác thì cơ quan, người có thẩm quyền tiếp nhận, giải quyết thủ tục hành chính yêu cầu cá nhân, tổ chức bổ sung thành phần hồ sơ để giải quyết thủ tục hành chính; đồng thời đề nghị cá nhân, tổ chức thực hiện cập nhật, điều chỉnh thông tin trong các cơ sở dữ liệu theo quy định của pháp luật.", "co_quan_thuc_hien": "- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).\n- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.", "thanh_phan_ho_so": "Bản chính hoặc bản sao có chứng thực hoặc bản sao điện tử được chứng thực từ bản chính của giấy chứng nhận quyền sở hữu, quyền sử dụng hoặc giấy tờ thay thế được pháp luật quy định đối với tài sản mà pháp luật quy định phải đăng ký quyền sở hữu, quyền sử dụng trong trường hợp văn bản từ chối nhận di sản liên quan đến tài sản đó. Trường hợp nộp hồ sơ trực tiếp, người yêu cầu chứng thực có thể nộp bản sao kèm xuất trình bản chính để đối chiếu (Không yêu cầu người yêu cầu chứng thực nộp giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất khi người tiếp nhận, giải quyết thủ tục hành chính khai thác được thông tin trên Cơ sở dữ liệu quốc gia về đất đai, giai đoạn đầu áp dụng đối với đất ở)\nDự thảo văn bản từ chối nhận di sản", "thoi_han_le_phi": "Thủ tục: Chứng thực văn bản từ chối nhận di sản. Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: DIRECT: 0 ngày | ONLINE: 0 ngày | POSTAL: 0 ngày. Mức phí/lệ phí: /văn bản. – /văn bản", "can_cu_phap_ly": "18/2026/NĐ-CP\n66.7/2025/NQ-CP\n23/2015/NĐ-CP\n226/2016/TT-BTC\n280/2025/NĐ-CP"}'),
('TTHC-CT-08', '2.001019', 'Chứng thực di chúc', 'Chứng thực', '- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).
- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.', 'Thủ tục: Chứng thực di chúc. Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: ONLINE: 0 ngày | DIRECT: 0 ngày | POSTAL: 0 ngày. Mức phí/lệ phí: /di chúc.', '/di chúc', 'https://dichvucong.gov.vn (API ID: 019d2bfd-95f0-7610-845f-c097f144bd55)', '{"trinh_tu": "+ Người yêu cầu chứng thực xuất trình một trong các giấy tờ sau: Căn cước điện tử; bản chính hoặc bản sao của Thẻ căn cước công dân hoặc Thẻ căn cước hoặc Giấy chứng nhận căn cước hoặc Hộ chiếu hoặc giấy tờ xuất nhập cảnh hoặc giấy tờ có giá trị đi lại quốc tế còn giá trị sử dụng và nộp 01 bộ hồ sơ yêu cầu chứng thực.\n\n+ Người thực hiện chứng thực (hoặc người tiếp nhận hồ sơ) kiểm tra giấy tờ trong hồ sơ yêu cầu chứng thực, nếu đầy đủ, tại thời điểm chứng thực người lập di chúc tự nguyện, minh mẫn và nhận thức, làm chủ được hành vi của mình thì thực hiện chứng thực.\n\n+ Người lập di chúc phải ký trước mặt người thực hiện chứng thực, nếu di chúc có từ 02 (hai) trang trở lên thì phải ký vào từng trang. Trường hợp người yêu cầu chứng thực nộp hồ sơ tại Trung tâm Phục vụ hành chính công cấp xã thì các bên tham gia giao dịch phải ký trước mặt người tiếp nhận hồ sơ.\n\n+ Trường hợp người yêu cầu chứng thực không ký được thì phải điểm chỉ; nếu người đó không đọc được, không nghe được, không ký, không điểm chỉ được thì phải có 02 (hai) người làm chứng. Người làm chứng phải có đủ năng lực hành vi dân sự và không có quyền, lợi ích hoặc nghĩa vụ liên quan đến di chúc. Người làm chứng do người yêu cầu chứng thực bố trí. Trường hợp người yêu cầu chứng thực không bố trí được thì đề nghị cơ quan thực hiện chứng thực chỉ định người làm chứng.\n\n+ Người thực hiện chứng thực (hoặc người tiếp nhận hồ sơ) ghi lời chứng di chúc theo mẫu quy định. Trường hợp tiếp nhận hồ sơ tại Trung tâm Phục vụ hành chính công cấp xã thì người tiếp nhận hồ sơ ký vào từng trang của di chúc và ký vào dưới lời chứng theo mẫu quy định.\n\nNgười thực hiện chứng thực ký vào từng trang của di chúc (nếu hồ sơ không được tiếp nhận qua Trung tâm Phục vụ hành chính công cấp xã), ký, ghi rõ họ tên, đóng dấu của cơ quan thực hiện chứng thực và ghi vào sổ chứng thực.\n\nĐối với di chúc có từ 02 (hai) trang trở lên, thì từng trang phải được đánh số thứ tự, có chữ ký của người yêu cầu chứng thực và người thực hiện chứng thực; số lượng trang và lời chứng được ghi tại trang cuối của di chúc. Trường hợp di chúc có từ 02 (hai) tờ trở lên thì phải đóng dấu giáp lai.\n\n+ Trong trường hợp người yêu cầu chứng thực không thông thạo tiếng Việt thì phải có người phiên dịch. Người phiên dịch phải là người có năng lực hành vi dân sự đầy đủ theo quy định của pháp luật, thông thạo tiếng Việt và ngôn ngữ mà người yêu cầu chứng thực sử dụng. Người phiên dịch do người yêu cầu chứng thực mời hoặc do cơ quan thực hiện chứng thực chỉ định. Thù lao phiên dịch do người yêu cầu chứng thực trả. Người phiên dịch có trách nhiệm dịch đầy đủ, chính xác nội dung của di chúc, nội dung lời chứng cho người yêu cầu chứng thực và ký vào từng trang di chúc với tư cách là người phiên dịch.\n\n+ Không yêu cầu người yêu cầu chứng thực nộp, xuất trình bản chính thức hoặc bản sao các giấy tờ, tài liệu mà các thông tin trong các giấy tờ, tài liệu đã có dữ liệu trong các cơ sở dữ liệu được cơ quan chủ quản cơ sở dữ liệu công bố.\n\n+ Người thực hiện chứng thực khai thác, sử dụng thông tin đã có trong các cơ sở dữ liệu để thay thế thành phần hồ sơ giải quyết thủ tục hành chính. Trường hợp không khai thác được thông tin hoặc thông tin khai thác được không đầy đủ, không chính xác thì cơ quan, người có thẩm quyền tiếp nhận, giải quyết thủ tục hành chính yêu cầu cá nhân, tổ chức bổ sung thành phần hồ sơ để giải quyết thủ tục hành chính; đồng thời đề nghị cá nhân, tổ chức thực hiện cập nhật, điều chỉnh thông tin trong các cơ sở dữ liệu theo quy định của pháp luật.", "co_quan_thuc_hien": "- Cơ quan tiếp nhận & trả kết quả: Trung tâm Phục vụ hành chính công cấp xã (NĐ 118/2025, sửa đổi bởi NĐ 367/2025 & NĐ 309/2026).\n- Cơ quan thẩm định & ký kết quả: Công chức chuyên môn thẩm định → Lãnh đạo UBND cấp xã ký duyệt.", "thanh_phan_ho_so": "Bản chính hoặc bản sao có chứng thực hoặc bản sao điện tử được chứng thực từ bản chính của giấy chứng nhận quyền sở hữu, quyền sử dụng hoặc giấy tờ thay thế được pháp luật quy định đối với tài sản mà pháp luật quy định phải đăng ký quyền sở hữu, quyền sử dụng trong trường hợp giao dịch liên quan đến tài sản đó; trừ trường hợp người lập di chúc đang bị cái chết đe dọa đến tính mạng. Trường hợp nộp hồ sơ trực tiếp, người yêu cầu chứng thực có thể nộp bản sao kèm xuất trình bản chính để đối chiếu.\n+ Dự thảo di chúc;", "thoi_han_le_phi": "Thủ tục: Chứng thực di chúc. Cơ quan có thẩm quyền giải quyết: Bộ Tư pháp. Thời hạn giải quyết: ONLINE: 0 ngày | DIRECT: 0 ngày | POSTAL: 0 ngày. Mức phí/lệ phí: /di chúc. – /di chúc", "can_cu_phap_ly": "66.7/2025/NQ-CP\n23/2015/NĐ-CP\n226/2016/TT-BTC\n280/2025/NĐ-CP\n01/2020/TT-BTP\n18/2026/NĐ-CP"}'),
('TTHC-DC-01', '3.000758', 'Đăng ký biến động quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất', 'Địa chính', '- Cơ quan tiếp nhận: Trung tâm Phục vụ hành chính công cấp tỉnh/cấp xã (phi địa giới trong tỉnh theo NĐ 151/2025/NĐ-CP).
- Cơ quan thẩm định & ký kết quả: Chi nhánh Văn phòng Đăng ký đất đai tỉnh An Giang (liên thông Cơ quan Thuế; UBND xã không ký).', 'Thủ tục: (An Giang) Đăng ký biến động quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất trong các trường hợp chuyển đổi quyền sử dụng đất nông nghiệp mà không theo phương án dồn điền, đổi thửa; chuyển nhượng, thừa kế, tặng cho quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất, góp vốn bằng quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất (kể cả tặng cho quyền sử dụng đất cho Nhà nước hoặc cộng đồng dân cư hoặc mở rộng đường giao thông); cho thuê, cho thuê lại quyền sử dụng đất trong dự án xây dựng kinh doanh kết cấu hạ tầng; bán hoặc tặng cho hoặc để thừa kế hoặc góp vốn bằng tài sản gắn liền với đất thuê của Nhà nước theo hình thức thuê đất trả tiền hàng năm. Cơ quan có thẩm quyền giải quyết: UBND tỉnh An Giang / UBND cấp xã theo phân cấp. Thời hạn giải quyết: DIRECT: - Đối với thủ tục chuyển đổi quyền sử dụng đất nông nghiệp mà không theo phương án dồn điền, đổi thửa hoặc trường hợp chuyển nhượng, thừa kế, tặng cho quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất, góp vốn bằng quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất; bán, thừa kế, tặng cho hoặc góp vốn bằng tài sản gắn liền với đất được Nhà nước cho thuê đất thu tiền thuê đất hằng năm:
+ Cơ quan, người có thẩm quyền thực hiện đăng ký đất đai, cấp Giấy chứng nhận quyền sử dụng đất, tài sản gắn liền với đất: không quá 08 ngày làm việc; 
+ Cơ quan thuế xác định nghĩa vụ tài chính: không quá 03 ngày làm việc; 
+ Thời gian trích đo bản đồ địa chính (nếu có): không quá 05 ngày làm việc; 
+ Người sử dụng đất nhận kết quả giải quyết thủ tục hành chính: không quá 02 ngày làm việc kể từ khi có thông tin từ cơ sở dữ liệu được liên thông hoặc chứng từ hoặc giấy tờ chứng minh đã hoàn thành nghĩa vụ tài chính.
Đối với các xã miền núi, hải đảo, vùng sâu, vùng xa, vùng có điều kiện kinh tế - xã hội khó khăn, vùng có điều kiện kinh tế - xã hội đặc biệt khó khăn thì thời gian thực hiện được tăng thêm 10 ngày làm việc.
- Đối với thủ tục cho thuê, cho thuê lại quyền sử dụng đất trong dự án xây dựng kinh doanh kết cấu hạ tầng: 
+ Cơ quan, người có thẩm quyền thực hiện đăng ký đất đai, cấp Giấy chứng nhận quyền sử dụng đất, tài sản gắn liền với đất: không quá 04 ngày làm việc;
+ Cơ quan thuế xác định nghĩa vụ tài chính: không quá 03 ngày làm việc; 
+ Thời gian trích đo bản đồ địa chính (nếu có): không quá 05 ngày làm việc; 
+ Người sử dụng đất nhận kết quả giải quyết thủ tục hành chính: không quá 02 ngày làm việc kể từ khi có thông tin từ cơ sở dữ liệu được liên thông hoặc chứng từ hoặc giấy tờ chứng minh đã hoàn thành nghĩa vụ tài chính.
Đối với các xã miền núi, hải đảo, vùng sâu, vùng xa, vùng có điều kiện kinh tế - xã hội khó khăn, vùng có điều kiện kinh tế - xã hội đặc biệt khó khăn thì thời gian thực hiện được tăng thêm 10 ngày làm việc.
4.2. Trường hợp hồ sơ chưa đầy đủ, chưa hợp lệ thì trong thời gian không quá 03 ngày làm việc, Văn phòng đăng ký đất đai thành phố hoặc Chi nhánh Văn phòng đăng ký đất đai phải thông báo và hướng dẫn người nộp hồ sơ bổ sung, hoàn chỉnh hồ sơ theo quy định | ONLINE: - Đối với thủ tục chuyển đổi quyền sử dụng đất nông nghiệp mà không theo phương án dồn điền, đổi thửa hoặc trường hợp chuyển nhượng, thừa kế, tặng cho quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất, góp vốn bằng quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất; bán, thừa kế, tặng cho hoặc góp vốn bằng tài sản gắn liền với đất được Nhà nước cho thuê đất thu tiền thuê đất hằng năm:
